"""Graph construction, the CSR representation, and selectable read backends.

Nodes are strings. Edges carry a numeric weight (default 1.0). Iteration order is always sorted, so
every algorithm in this package is deterministic without depending on insertion order.

The mutable adjacency dict stays the single write layer -- ``add_node``, ``add_edge`` and
``remove_edge`` keep exactly their old semantics (undirected mirroring, self-loops, last-write-wins
on duplicates). ``configure_storage`` adds an optional read layer that ``nodes``, ``neighbors``,
``edges``, ``degree`` and every algorithm consult instead:

* ``csr``   -- compressed sparse row: an 8-byte offset per node boundary plus a flattened
               16-byte (node id, weight) neighbour list, both kept sorted by node name;
* ``dense`` -- an n*n presence byte plus an n*n float64 weight, 9 bytes per cell. The presence byte
               is what lets a zero-weight edge stay distinct from a pair that has no edge;
* ``auto``  -- the smaller of the two logical footprints, CSR winning ties and every empty graph.

A revision counter invalidates the arrays: any mutation rebuilds lazily on the next query, so a
switched graph still supports ``add_node``/``add_edge``/``remove_edge`` and immediately reflects them.
"""

from __future__ import annotations

import math
from array import array
from dataclasses import dataclass, field

from .errors import ValidationError

DENSE_LIMIT_BYTES = 536870912
STORAGE_CHOICES = ("adjacency", "csr", "dense", "auto")


def _validated_weight(weight: object) -> float:
    """Normalise an edge weight to float, or raise ValidationError.

    ``bool`` is rejected even though it subclasses ``int``; strings and ``None`` are rejected even
    though ``float()`` would accept some of them; and NaN plus the two infinities are rejected
    because a single non-finite value poisons every distance, rank and JSON document it reaches.
    Negative finite values are legal -- Bellman-Ford needs them.
    """
    if isinstance(weight, bool) or not isinstance(weight, (int, float)):
        raise ValidationError("edge weight must be a finite number", value=weight)
    value = float(weight)
    if not math.isfinite(value):
        raise ValidationError("edge weight must be finite")
    return value


@dataclass(frozen=True, slots=True)
class Edge:
    source: str
    target: str
    weight: float = 1.0

    def __post_init__(self) -> None:
        if not self.source or not self.target:
            raise ValidationError("edge endpoints must be non-empty", value=f"{self.source!r}->{self.target!r}")
        object.__setattr__(self, "weight", _validated_weight(self.weight))

    def to_document(self) -> dict[str, object]:
        return {"source": self.source, "target": self.target, "weight": float(self.weight)}


@dataclass(slots=True)
class Graph:
    directed: bool = False
    _adjacency: dict[str, dict[str, float]] = field(default_factory=dict, init=False)

    # Backend actually read on queries: "adjacency" (the default), "csr" or "dense". ``auto`` is
    # resolved at selection time, so this field always names the materialised backend.
    _storage: str = field(default="adjacency", init=False)
    # What the caller passed to configure_storage; "auto" is preserved here for the stats report.
    _storage_requested: str | None = field(default=None, init=False)
    # Bumped on every mutation; the arrays carry the revision they were built at and rebuild
    # lazily whenever it lags (a same-shape weight overwrite must invalidate too).
    _revision: int = field(default=0, init=False)
    _built_revision: int = field(default=-1, init=False)
    # CSR arrays.
    _csr_nodes: list[str] = field(default_factory=list, init=False)
    _csr_offsets: array = field(default_factory=lambda: array("q"), init=False)
    _csr_columns: array = field(default_factory=lambda: array("q"), init=False)
    _csr_weights: array = field(default_factory=lambda: array("d"), init=False)
    # Dense arrays. _dense_present[row * n + col] distinguishes a stored edge (its weight may be 0)
    # from a pair with no edge at all.
    _dense_nodes: list[str] = field(default_factory=list, init=False)
    _dense_index: dict[str, int] = field(default_factory=dict, init=False)
    _dense_present: bytearray = field(default_factory=bytearray, init=False)
    _dense_weights: array = field(default_factory=lambda: array("d"), init=False)

    # -- construction ----------------------------------------------------------------------------
    def add_node(self, node: str) -> None:
        if not node:
            raise ValidationError("node name must be non-empty")
        if node not in self._adjacency:
            self._adjacency[node] = {}
            self._revision += 1

    def add_edge(self, source: str, target: str, weight: float = 1.0) -> None:
        # Validate before touching any state: a rejected weight must add neither endpoint, overwrite
        # no existing edge, and -- for an undirected graph -- never leave just one half behind.
        value = _validated_weight(weight)
        self.add_node(source)
        self.add_node(target)
        if self.directed:
            self._adjacency[source][target] = value
        else:
            self._adjacency[source][target] = value
            self._adjacency[target][source] = value
        # A write of adjacency -- new arc or last-write-wins overwrite -- invalidates the arrays.
        self._revision += 1

    def remove_edge(self, source: str, target: str) -> bool:
        removed = False
        if source in self._adjacency and target in self._adjacency[source]:
            del self._adjacency[source][target]
            removed = True
        if not self.directed and target in self._adjacency and source in self._adjacency[target]:
            del self._adjacency[target][source]
            removed = True
        if removed:
            self._revision += 1
        return removed

    @classmethod
    def from_edges(cls, edges: list[Edge], *, directed: bool = False) -> "Graph":
        graph = cls(directed=directed)
        for edge in edges:
            graph.add_edge(edge.source, edge.target, edge.weight)
        return graph

    # -- storage selection -----------------------------------------------------------------------
    def storage_sizes(self) -> tuple[int, int, int]:
        """Logical footprints ``(adjacency_entries, csr_bytes, dense_bytes)``.

        ``n`` is the node count and ``a`` the total number of adjacency entries across every node:
        each directed arc counts once, an undirected non-self-loop edge counts twice (reachable from
        both ends) and a self-loop once. CSR is ``8*(n+1) + 16*a`` bytes; dense is ``9*n*n``.
        """
        n = len(self._adjacency)
        entries = sum(len(neighbours) for neighbours in self._adjacency.values())
        csr_bytes = 8 * (n + 1) + 16 * entries
        dense_bytes = 9 * n * n
        return entries, csr_bytes, dense_bytes

    def _build_csr(self) -> None:
        nodes = sorted(self._adjacency)
        index = {node: position for position, node in enumerate(nodes)}
        offsets = array("q", [0])
        columns = array("q")
        weights = array("d")
        for node in nodes:
            for target in sorted(self._adjacency[node]):
                columns.append(index[target])
                weights.append(self._adjacency[node][target])
            offsets.append(len(columns))
        self._csr_nodes, self._csr_offsets = nodes, offsets
        self._csr_columns, self._csr_weights = columns, weights

    def _build_dense(self) -> None:
        nodes = sorted(self._adjacency)
        n = len(nodes)
        required = 9 * n * n
        # The limit holds for the lazy post-mutation rebuild too: a graph that grew past it must
        # never attempt the allocation on its next query.
        if required > DENSE_LIMIT_BYTES:
            raise ValidationError(
                "dense storage exceeds the allocation limit",
                requestedBytes=required,
                limitBytes=DENSE_LIMIT_BYTES,
            )
        index = {node: position for position, node in enumerate(nodes)}
        present = bytearray(n * n)
        weights = array("d", [0.0]) * (n * n)
        for source in nodes:
            row = index[source] * n
            for target, weight in self._adjacency[source].items():
                cell = row + index[target]
                present[cell] = 1
                weights[cell] = weight
        self._dense_nodes, self._dense_index = nodes, index
        self._dense_present, self._dense_weights = present, weights

    def configure_storage(self, requested: str = "adjacency") -> dict[str, object]:
        """Select the backend used by every read, and return the stable stats ``storage`` document.

        ``adjacency`` restores the mutable dict. ``csr`` and ``dense`` materialise their arrays now
        (and re-materialise lazily after any mutation). ``auto`` compares the logical footprints
        after a full load and keeps the smaller one -- CSR on a tie, and always CSR for an empty
        graph; an oversized dense candidate under ``auto`` also falls back to CSR. An explicit
        ``dense`` whose matrix would exceed ``DENSE_LIMIT_BYTES`` is refused before any allocation.
        """
        if requested not in STORAGE_CHOICES:
            raise ValidationError(
                f"storage must be one of {', '.join(STORAGE_CHOICES)}",
                value=requested,
            )
        entries, csr_bytes, dense_bytes = self.storage_sizes()
        n = len(self._adjacency)
        selected = requested
        if requested == "auto":
            selected = "csr" if n == 0 or csr_bytes <= dense_bytes else "dense"
            if selected == "dense" and dense_bytes > DENSE_LIMIT_BYTES:
                selected = "csr"
        if selected == "dense":
            if dense_bytes > DENSE_LIMIT_BYTES:
                raise ValidationError(
                    "dense storage exceeds the allocation limit",
                    requestedBytes=dense_bytes,
                    limitBytes=DENSE_LIMIT_BYTES,
                )
            self._build_dense()
        elif selected == "csr":
            self._build_csr()
        self._storage = selected
        self._storage_requested = requested
        self._built_revision = self._revision
        return self.storage_document()

    def _ensure_storage(self) -> None:
        """Rebuild the active arrays if a mutation happened after they were built."""
        if self._built_revision == self._revision:
            return
        if self._storage == "csr":
            self._build_csr()
        elif self._storage == "dense":
            self._build_dense()
        self._built_revision = self._revision

    def storage_document(self) -> dict[str, object]:
        """The ``storage`` object stats emits: request, selection, footprints and density."""
        entries, csr_bytes, dense_bytes = self.storage_sizes()
        n = len(self._adjacency)
        density = round(entries / (n * n), 10) if n else 0
        # adjacency has no formula of its own: its logical footprint is the same adjacency entries
        # laid out as CSR, which is the encoding csr() already exports.
        logical_bytes = {"adjacency": csr_bytes, "csr": csr_bytes, "dense": dense_bytes}[self._storage]
        return {
            "requested": self._storage_requested or "adjacency",
            "selected": self._storage,
            "logicalBytes": logical_bytes,
            "csrBytes": csr_bytes,
            "denseBytes": dense_bytes,
            "adjacencyEntries": entries,
            "density": density,
        }

    # -- queries ---------------------------------------------------------------------------------
    @property
    def node_count(self) -> int:
        return len(self._adjacency)

    def nodes(self) -> list[str]:
        if self._storage == "csr":
            self._ensure_storage()
            return list(self._csr_nodes)
        if self._storage == "dense":
            self._ensure_storage()
            return list(self._dense_nodes)
        return sorted(self._adjacency)

    def neighbors(self, node: str) -> list[tuple[str, float]]:
        if self._storage == "csr":
            self._ensure_storage()
            try:
                row = self._csr_nodes.index(node)
            except ValueError:
                raise ValidationError(f"unknown node: {node}", known=list(self._csr_nodes[:10])) from None
            start, end = self._csr_offsets[row], self._csr_offsets[row + 1]
            return [
                (self._csr_nodes[self._csr_columns[position]], self._csr_weights[position])
                for position in range(start, end)
            ]
        if self._storage == "dense":
            self._ensure_storage()
            if node not in self._dense_index:
                raise ValidationError(f"unknown node: {node}", known=list(self._dense_nodes[:10]))
            n = len(self._dense_nodes)
            row = self._dense_index[node] * n
            return [
                (self._dense_nodes[column], self._dense_weights[row + column])
                for column in range(n)
                if self._dense_present[row + column]
            ]
        if node not in self._adjacency:
            raise ValidationError(f"unknown node: {node}", known=self.nodes()[:10])
        return [(target, self._adjacency[node][target]) for target in sorted(self._adjacency[node])]

    def edges(self) -> list[Edge]:
        seen: set[tuple[str, str]] = set()
        result: list[Edge] = []
        for source in self.nodes():
            for target, weight in self.neighbors(source):
                if not self.directed and (target, source) in seen:
                    continue
                seen.add((source, target))
                result.append(Edge(source, target, weight))
        return result

    def edge_count(self) -> int:
        return len(self.edges())

    def degree(self, node: str) -> int:
        return len(self.neighbors(node))

    def weighted_degree(self, node: str) -> float:
        # Adjacency keeps the historical summation order (dict values) exactly; the array backends
        # read their own weights. Float addition is not associative, so the order must not drift.
        self.neighbors(node)
        if self._storage == "adjacency":
            return sum(self._adjacency[node].values())
        return sum(weight for _, weight in self.neighbors(node))

    def self_loops(self) -> list[str]:
        return [node for node in self.nodes() if any(neighbour == node for neighbour, _ in self.neighbors(node))]

    def has_negative_weights(self) -> bool:
        return any(edge.weight < 0 for edge in self.edges())

    def csr(self) -> tuple[list[str], list[int], list[tuple[str, float]]]:
        """Compressed sparse row: node order, offsets, and the flattened neighbour list."""
        if self._storage == "csr":
            self._ensure_storage()
            nodes = list(self._csr_nodes)
            offsets = list(self._csr_offsets)
            flat = [
                (nodes[self._csr_columns[position]], self._csr_weights[position])
                for position in range(len(self._csr_columns))
            ]
            return nodes, offsets, flat
        nodes = self.nodes()
        offsets = [0]
        flat: list[tuple[str, float]] = []
        for node in nodes:
            flat.extend(self.neighbors(node))
            offsets.append(len(flat))
        return nodes, offsets, flat

    def to_document(self) -> dict[str, object]:
        return {
            "directed": self.directed,
            "nodes": self.node_count,
            "edges": self.edge_count(),
            "selfLoops": self.self_loops(),
            "negativeWeights": self.has_negative_weights(),
        }

"""Graph algorithms: traversal, shortest paths, components, ordering, PageRank, centrality, clustering, communities.

Every function is deterministic (sorted iteration), reports unreachable nodes explicitly rather than
inventing a distance, and raises a typed error with evidence when the input makes the answer
undefined -- a negative edge for Dijkstra, a negative cycle for Bellman-Ford, a cycle for a
topological sort.
"""

from __future__ import annotations

import heapq
import math
from dataclasses import dataclass
from typing import Mapping

from .errors import CycleError, NegativeCycleError, NegativeWeightError, ValidationError
from .graph import Graph

INFINITY = math.inf


def _check_source(graph: Graph, source: str) -> None:
    if source not in graph.nodes():
        raise ValidationError(f"unknown source: {source}", known=graph.nodes()[:10])


def bfs(graph: Graph, source: str) -> dict[str, int]:
    """Hop distances from `source`; unreachable nodes are absent (never faked as -1)."""
    _check_source(graph, source)
    seen = {source: 0}
    queue = [source]
    head = 0
    while head < len(queue):
        node = queue[head]
        head += 1
        for neighbour, _ in graph.neighbors(node):
            if neighbour not in seen:
                seen[neighbour] = seen[node] + 1
                queue.append(neighbour)
    return seen


def dfs(graph: Graph, source: str) -> list[str]:
    """Pre-order depth-first walk, neighbours visited in sorted order."""
    _check_source(graph, source)
    visited: list[str] = []
    seen: set[str] = set()
    stack = [source]
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        visited.append(node)
        stack.extend(neighbour for neighbour, _ in reversed(graph.neighbors(node)) if neighbour not in seen)
    return visited


def dijkstra(graph: Graph, source: str) -> tuple[dict[str, float], dict[str, str | None]]:
    """Non-negative shortest paths; a negative edge is refused, not silently mis-answered.

    The check walks every edge once, up front: discovering a negative weight halfway through the
    relaxation loop would mean returning a distance that is simply wrong.
    """
    _check_source(graph, source)
    for edge in graph.edges():
        if edge.weight < 0:
            raise NegativeWeightError(
                "dijkstra requires non-negative weights; use bellman_ford",
                edge=f"{edge.source}->{edge.target}",
                weight=edge.weight,
            )
    distance: dict[str, float] = {source: 0.0}
    previous: dict[str, str | None] = {source: None}
    remaining = set(graph.nodes())
    while remaining:
        current = None
        best = INFINITY
        for node in sorted(remaining):
            if node in distance and distance[node] < best:
                current, best = node, distance[node]
        if current is None:
            break
        remaining.discard(current)
        for neighbour, weight in graph.neighbors(current):
            candidate = distance[current] + weight
            if neighbour not in distance or candidate < distance[neighbour]:
                distance[neighbour] = candidate
                previous[neighbour] = current
    return distance, previous


def bellman_ford(graph: Graph, source: str) -> tuple[dict[str, float], dict[str, str | None]]:
    """Shortest paths with negative weights; reports the offending cycle when one exists."""
    _check_source(graph, source)
    distance: dict[str, float] = {source: 0.0}
    previous: dict[str, str | None] = {source: None}
    nodes = graph.nodes()
    for _ in range(len(nodes) - 1):
        changed = False
        for node in nodes:
            if node not in distance:
                continue
            for neighbour, weight in graph.neighbors(node):
                candidate = distance[node] + weight
                if neighbour not in distance or candidate < distance[neighbour]:
                    distance[neighbour] = candidate
                    previous[neighbour] = node
                    changed = True
        if not changed:
            break
    for node in nodes:
        if node not in distance:
            continue
        for neighbour, weight in graph.neighbors(node):
            if neighbour not in distance or distance[node] + weight < distance[neighbour]:
                raise NegativeCycleError("negative cycle reachable from the source", at=f"{node}->{neighbour}")
    return distance, previous


def path_from(previous: dict[str, str | None], target: str) -> list[str]:
    """Reconstruct a path from a predecessor map; raises when the target is unreachable."""
    if target not in previous:
        raise ValidationError(f"unreachable target: {target}")
    path = [target]
    while previous[path[-1]] is not None:
        path.append(str(previous[path[-1]]))
    return list(reversed(path))


def _validated_heuristic(graph: Graph, target: str, heuristic: Mapping[str, float] | None) -> dict[str, float]:
    """Normalise the heuristic map, or raise ValidationError naming the first offending entry.

    Nodes missing from the map estimate to 0. Every supplied value must be a finite, non-negative
    number naming a node of the graph; the target must estimate to exactly 0; and along every
    traversable direction the estimate must be consistent -- h(u) <= weight(u, v) + h(v) -- which is
    what guarantees the first time the target leaves the frontier its distance is final. All checks
    walk nodes and edges in sorted order, so the reported violation never depends on the mapping's
    key order.
    """
    estimates = {node: 0.0 for node in graph.nodes()}
    if not heuristic:
        return estimates
    known = set(graph.nodes())
    for node in sorted(heuristic):
        value = heuristic[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            raise ValidationError("heuristic values must be finite numbers", node=node)
        estimate = float(value)
        if estimate < 0:
            raise ValidationError("heuristic values must be non-negative", node=node, value=estimate)
        if node not in known:
            raise ValidationError(f"heuristic names an unknown node: {node}", known=graph.nodes()[:10])
        estimates[node] = estimate
    if estimates[target] != 0.0:
        raise ValidationError("heuristic for the target must be 0", target=target, value=estimates[target])
    # A small tolerance keeps float summation noise (0.1 + 0.2) from reading as a violation; a real
    # inconsistency exceeds it by construction.
    for node in graph.nodes():
        for neighbour, weight in graph.neighbors(node):
            if estimates[node] > weight + estimates[neighbour] + 1e-9:
                raise ValidationError(
                    "heuristic is not consistent: h(u) must not exceed weight(u, v) + h(v)",
                    edge=f"{node}->{neighbour}",
                    estimate=estimates[node],
                    bound=round(weight + estimates[neighbour], 10),
                )
    return estimates


def astar(
    graph: Graph,
    source: str,
    target: str,
    heuristic: Mapping[str, float] | None = None,
) -> tuple[float, dict[str, str | None], int]:
    """Goal-directed shortest path from `source` to `target` guided by a consistent heuristic.

    Returns the distance to `target`, a predecessor map `path_from` can rebuild the route from, and
    the number of distinct nodes expanded. The frontier is a heap keyed by (estimated total cost,
    node name), so equal-cost candidates and equal-cost paths are always settled by node name; with
    an empty heuristic the search degenerates to Dijkstra and agrees with it exactly. A negative
    edge is refused up front, an unreachable target raises rather than inventing a distance.
    """
    _check_source(graph, source)
    if target not in graph.nodes():
        raise ValidationError(f"unknown target: {target}", known=graph.nodes()[:10])
    for edge in graph.edges():
        if edge.weight < 0:
            raise NegativeWeightError(
                "astar requires non-negative weights; use bellman_ford",
                edge=f"{edge.source}->{edge.target}",
                weight=edge.weight,
            )
    estimates = _validated_heuristic(graph, target, heuristic)
    distance: dict[str, float] = {source: 0.0}
    previous: dict[str, str | None] = {source: None}
    frontier: list[tuple[float, str]] = [(estimates[source], source)]
    expanded: set[str] = set()
    while frontier:
        _, current = heapq.heappop(frontier)
        if current in expanded:
            continue
        expanded.add(current)
        if current == target:
            return distance[target], previous, len(expanded)
        for neighbour, weight in graph.neighbors(current):
            if neighbour in expanded:
                continue
            candidate = distance[current] + weight
            if neighbour not in distance or candidate < distance[neighbour]:
                distance[neighbour] = candidate
                previous[neighbour] = current
                heapq.heappush(frontier, (candidate + estimates[neighbour], neighbour))
    raise ValidationError(f"unreachable target: {target}")


def components(graph: Graph) -> list[list[str]]:
    """Weakly connected components, each sorted, the list ordered by its smallest node."""
    undirected = graph if not graph.directed else _as_undirected(graph)
    seen: set[str] = set()
    groups: list[list[str]] = []
    for node in undirected.nodes():
        if node in seen:
            continue
        group = sorted(bfs(undirected, node))
        seen.update(group)
        groups.append(group)
    return groups


def _as_undirected(graph: Graph) -> Graph:
    mirror = Graph(directed=False)
    # Seed every node before mirroring the edges: a node with no incident arc -- added on its own via
    # add_node or orphaned by remove_edge -- cannot be recovered from the edge list, yet it must
    # survive the undirected reading as a singleton component.
    for node in graph.nodes():
        mirror.add_node(node)
    for edge in graph.edges():
        mirror.add_edge(edge.source, edge.target, edge.weight)
    return mirror


def topological_sort(graph: Graph) -> list[str]:
    """Kahn's algorithm; a cycle is reported with the nodes that could never be released."""
    if not graph.directed:
        raise ValidationError("topological sort requires a directed graph")
    in_degree = {node: 0 for node in graph.nodes()}
    for node in graph.nodes():
        for neighbour, _ in graph.neighbors(node):
            in_degree[neighbour] += 1
    ready = sorted(node for node, degree in in_degree.items() if degree == 0)
    order: list[str] = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for neighbour, _ in graph.neighbors(node):
            in_degree[neighbour] -= 1
            if in_degree[neighbour] == 0:
                ready.append(neighbour)
                ready.sort()
    if len(order) != graph.node_count:
        stuck = sorted(node for node, degree in in_degree.items() if degree > 0)
        raise CycleError("directed cycle prevents a topological order", cycle=stuck)
    return order


@dataclass(frozen=True, slots=True)
class PageRankResult:
    scores: dict[str, float]
    iterations: int
    converged: bool

    def to_document(self) -> dict[str, object]:
        return {"iterations": self.iterations, "converged": self.converged, "scores": {node: round(value, 10) for node, value in sorted(self.scores.items())}}


def pagerank(graph: Graph, *, damping: float = 0.85, tolerance: float = 1e-9, max_iterations: int = 200) -> PageRankResult:
    """Power iteration with explicit convergence reporting (never a silent iteration cap).

    Edge weights are transition shares, so a negative one would yield negative scores, a zero
    outgoing-weight sum that divides through to nonsense, or a total that is not one. The whole
    graph participates in the redistribution -- an edge in an isolated component is not exempt -- so
    every edge is checked up front in the graph's stable edge order and a negative weight is refused
    with that edge as evidence; a zero total is fine, it simply marks a dangling node.
    """
    if not 0.0 < damping < 1.0:
        raise ValidationError("damping must be in (0, 1)", value=damping)
    for edge in graph.edges():
        if edge.weight < 0:
            raise NegativeWeightError(
                "pagerank requires non-negative edge weights",
                edge=f"{edge.source}->{edge.target}",
                weight=edge.weight,
            )
    nodes = graph.nodes()
    if not nodes:
        return PageRankResult({}, 0, True)
    total = len(nodes)
    scores = {node: 1.0 / total for node in nodes}
    outgoing = {node: sum(weight for _, weight in graph.neighbors(node)) for node in nodes}
    # Incoming edges are collected once, outside the iteration loop: rebuilding the neighbour mapping
    # inside it was both quadratic and wasteful (the first version of this function did exactly that).
    incoming_edges: dict[str, list[tuple[str, float]]] = {node: [] for node in nodes}
    for node in nodes:
        for neighbour, weight in graph.neighbors(node):
            incoming_edges[neighbour].append((node, weight))
    converged = False
    iterations = 0
    for iterations in range(1, max_iterations + 1):
        dangling = sum(scores[node] for node in nodes if outgoing[node] == 0)
        updated: dict[str, float] = {}
        for node in nodes:
            incoming = 0.0
            for other, weight in incoming_edges[node]:
                if outgoing[other] > 0:
                    incoming += scores[other] * weight / outgoing[other]
            updated[node] = (1.0 - damping) / total + damping * (incoming + dangling / total)
        delta = sum(abs(updated[node] - scores[node]) for node in nodes)
        scores = updated
        if delta < tolerance:
            converged = True
            break
    return PageRankResult(scores, iterations, converged)


def degree_centrality(graph: Graph) -> dict[str, float]:
    """Degree normality: degree divided by the largest possible degree in an undirected reading."""
    total = graph.node_count
    if total <= 1:
        return {node: 0.0 for node in graph.nodes()}
    denominator = float(total - 1)
    return {node: round(graph.degree(node) / denominator, 10) for node in graph.nodes()}


@dataclass(frozen=True, slots=True)
class ClusteringResult:
    coefficients: dict[str, float]
    average: float
    transitivity: float
    triangles: int
    connected_triples: int

    def to_document(self) -> dict[str, object]:
        return {
            "coefficients": {node: self.coefficients[node] for node in sorted(self.coefficients)},
            "average": self.average,
            "transitivity": self.transitivity,
            "triangles": self.triangles,
            "connectedTriples": self.connected_triples,
            "nodes": len(self.coefficients),
        }


def clustering(graph: Graph) -> ClusteringResult:
    """Local clustering coefficients, their average, and the global transitivity.

    Everything is measured on a simple undirected reading of the graph: an edge in either direction
    counts once, weights and duplicate adjacencies are ignored, and self-loops are neighbours of
    nobody. Every node -- including isolated ones -- is present in the result and counts towards the
    average. Each unordered triangle is counted once; a connected triple (wedge) is counted at its
    centre as a pair of distinct neighbours. All iteration is sorted, so the answer never depends on
    insertion order or set traversal.
    """
    # Built directly instead of via _as_undirected: that helper mirrors edges only, so an isolated
    # node in a directed graph would silently drop out of the average.
    adjacency: dict[str, set[str]] = {node: set() for node in graph.nodes()}
    for edge in graph.edges():
        if edge.source == edge.target:
            continue
        adjacency[edge.source].add(edge.target)
        adjacency[edge.target].add(edge.source)
    nodes = sorted(adjacency)
    coefficients: dict[str, float] = {}
    coefficient_sum = 0.0
    closed_pairs = 0
    wedges = 0
    for node in nodes:
        neighbours = sorted(adjacency[node])
        degree = len(neighbours)
        pairs = degree * (degree - 1) // 2
        if degree < 2:
            coefficients[node] = 0.0
            continue
        # A linked pair of neighbours closes one wedge at this node; each triangle contributes at all
        # three of its vertices, so the total is three times the triangle count.
        between = sum(1 for index, left in enumerate(neighbours) for right in neighbours[index + 1 :] if right in adjacency[left])
        value = between / pairs
        coefficients[node] = round(value, 10)
        coefficient_sum += value
        closed_pairs += between
        wedges += pairs
    triangles = closed_pairs // 3
    average = round(coefficient_sum / len(nodes), 10) if nodes else 0.0
    transitivity = round(3 * triangles / wedges, 10) if wedges else 0.0
    return ClusteringResult(coefficients, average, transitivity, triangles, wedges)


@dataclass(frozen=True, slots=True)
class CommunitiesResult:
    communities: list[list[str]]
    labels: dict[str, str]
    iterations: int
    converged: bool

    @property
    def count(self) -> int:
        return len(self.communities)

    def to_document(self) -> dict[str, object]:
        return {
            "communities": self.communities,
            "labels": {node: self.labels[node] for node in sorted(self.labels)},
            "count": self.count,
            "iterations": self.iterations,
            "converged": self.converged,
        }


def label_propagation(graph: Graph, *, max_iterations: int = 100) -> CommunitiesResult:
    """Deterministic weighted label propagation over a simple undirected reading of the graph.

    The reading ignores self-loops and sums arcs between the same pair: an undirected edge
    contributes its weight once in each direction, and mutual arcs of a directed graph add up. Every
    node starts labelled with its own name; each round walks nodes in name order and moves a node to
    the neighbouring label with the highest summed edge weight, keeping the current label when it
    ties for the best score and otherwise preferring the lexicographically smallest tied label. A
    round with no change is convergence; hitting `max_iterations` first is reported honestly as
    `converged=False` with the deterministic labelling reached so far. Communities are the groups
    sharing a final label, each sorted by node name, the list ordered by each group's smallest node,
    and every output label is normalised to that smallest member -- so isolated nodes stay singleton
    communities and the document is byte-identical however the edges were ordered. Weights must be
    non-negative: the first negative edge in the graph's stable edge order is refused with that edge
    as evidence.
    """
    if isinstance(max_iterations, bool) or not isinstance(max_iterations, int) or max_iterations < 1:
        raise ValidationError("max_iterations must be an integer >= 1", value=max_iterations)
    for edge in graph.edges():
        if edge.weight < 0:
            raise NegativeWeightError(
                "label propagation requires non-negative edge weights",
                edge=f"{edge.source}->{edge.target}",
                weight=edge.weight,
            )
    nodes = graph.nodes()
    if not nodes:
        return CommunitiesResult([], {}, 0, True)
    adjacency: dict[str, dict[str, float]] = {node: {} for node in nodes}
    for edge in graph.edges():
        if edge.source == edge.target:
            continue
        adjacency[edge.source][edge.target] = adjacency[edge.source].get(edge.target, 0.0) + edge.weight
        adjacency[edge.target][edge.source] = adjacency[edge.target].get(edge.source, 0.0) + edge.weight
    labels = {node: node for node in nodes}
    converged = False
    iterations = 0
    for iterations in range(1, max_iterations + 1):
        changed = False
        for node in nodes:
            scores: dict[str, float] = {}
            for neighbour in sorted(adjacency[node]):
                label = labels[neighbour]
                scores[label] = scores.get(label, 0.0) + adjacency[node][neighbour]
            if not scores:
                continue
            best = max(scores.values())
            tied = {label for label, score in scores.items() if score == best}
            if labels[node] in tied:
                continue
            labels[node] = min(tied)
            changed = True
        if not changed:
            converged = True
            break
    groups: dict[str, list[str]] = {}
    for node in nodes:
        groups.setdefault(labels[node], []).append(node)
    # Members were appended in sorted node order, and lexicographic list ordering is then exactly
    # "ordered by the smallest member", which is the required community order.
    communities = sorted(groups.values())
    normalised = {node: members[0] for members in communities for node in members}
    return CommunitiesResult(communities, normalised, iterations, converged)

"""Exception hierarchy with stable `kind` values.

The three failure modes that matter for graph work each get their own type, because each one means
"the answer you asked for does not exist" rather than "the call was malformed": a negative edge under
Dijkstra, a negative cycle under Bellman-Ford, and a cycle under topological sort.
"""

from __future__ import annotations


class GraphError(Exception):
    """Base class for every error this package raises on purpose."""

    kind = "graph_error"

    def __init__(self, message: str, **context: object) -> None:
        super().__init__(message)
        self.message = message
        self.context = {key: value for key, value in context.items() if value is not None}

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {"error": self.kind, "message": self.message}
        document.update(self.context)
        return document


class ParseError(GraphError):
    """Malformed input rows or documents."""

    kind = "parse_error"

    def __init__(self, message: str, *, line: int | None = None, **context: object) -> None:
        super().__init__(message, line=line, **context)


class ValidationError(GraphError):
    """A request that is well-formed but not allowed: unknown node, undirected sort, bad damping."""

    kind = "validation_error"


class NegativeWeightError(GraphError):
    """An algorithm defined only for non-negative edges (Dijkstra, A*, PageRank) met a negative one."""

    kind = "negative_weight_error"


class NegativeCycleError(GraphError):
    """Bellman-Ford found a negative cycle reachable from the source: no finite answer exists."""

    kind = "negative_cycle_error"


class CycleError(GraphError):
    """A topological order was requested for a graph that has a directed cycle."""

    kind = "cycle_error"


class OutputError(GraphError):
    """The output target cannot be used safely."""

    kind = "output_error"

input.content:
"""Repeatable state-sequence differential tests across the storage backends.

One graph always stays on the mutable ``adjacency`` dict and is the isomorphism reference; three
twins replay the *exact* same fixed operation sequence on ``csr``, ``dense`` and ``auto``. After
every successful step the public observation surface is compared -- nodes, edges, neighbours,
degree, edge count, self loops, the CSR export, ``to_document``, storage footprints and the
selection report -- and, whenever the state's preconditions hold, the complete results of every
algorithm (BFS, DFS, Dijkstra, Bellman-Ford, components, centrality, clustering, PageRank, label
propagation; topological sort for directed acyclic states; A* with an all-zero heuristic for
reachable targets), plus a re-walk of every ``path_from`` reconstruction. The exception type and
evidence of identical calls must also agree across backends.

The sequences come from a tiny seeded integer generator (no third-party property library, no
clock or environment input): the same seeds always pick the same cases, and a failure names the
graph type, backend, seed and the first inconsistent step. The scenarios stably cover isolated
nodes, self-loops, zero-weight edges, duplicate overwrites, removing a missing edge, edits after
a switch, same-shape weight overwrites, and repeated switches between the materialised backends.
Empty node names and non-finite/non-numeric weights keep raising ``ValidationError`` and must
change neither nodes, edges, storage selection nor subsequent algorithm results; removing a
missing edge keeps returning ``False``.
"""

from __future__ import annotations

import math
import unittest

from graphtk import (
    Graph,
    NegativeCycleError,
    NegativeWeightError,
    ValidationError,
    astar,
    bellman_ford,
    bfs,
    clustering,
    components,
    degree_centrality,
    dfs,
    dijkstra,
    label_propagation,
    path_from,
    pagerank,
    topological_sort,
)

# Seeds are fixed lists: adding or removing a seed is an explicit, reviewable choice, never a
# random draw, so two runs of this file execute byte-for-byte identical cases.
SEQUENCE_SEEDS = list(range(40))
SWITCH_SEEDS = list(range(8))
MUTATION_SEEDS = list(range(10))
BACKENDS = ("csr", "dense", "auto")
ALL_SELECTIONS = ("adjacency", "csr", "dense", "auto")
NODE_NAMES = ("a", "b", "c", "d", "e", "f")

# Finite numbers only: a generated state never approaches the 512 MiB dense ceiling (n <= 6).
WEIGHT_CHOICES = (0, 0.0, 1, 2, -2, 3, -1, 4, 0, 1, 5, -3)

# Rejected by _validated_weight / add_node exactly the way the public API rejects them.
INVALID_WEIGHTS = (True, False, "1.5", None, float("nan"), float("inf"), float("-inf"))
INVALID_NAMES = ("",)


class SeededChoices:
    """Deterministic integer stream in the spirit of ``random.Random`` -- seeded, nothing else.

    Only ``randrange`` and ``choice`` are needed; a hand-rolled LCG keeps the case selection
    independent of hashing, process seeding and the wall clock.
    """

    __slots__ = ("state",)

    def __init__(self, seed: int) -> None:
        self.state = seed & 0xFFFFFFFF

    def randrange(self, stop: int) -> int:
        # Constants from Numerical Recipes; the low bits of an LCG are weak, so the next value is
        # taken from the high half.
        self.state = (1664525 * self.state + 1013904223) & 0xFFFFFFFF
        return (self.state >> 16) % stop

    def choice(self, options):
        return options[self.randrange(len(options))]


# -- operation records ----------------------------------------------------------------------------
# Every record is a tuple so a replayed step is trivially reproducible in a failure message:
#   ("node", name)                     add_node
#   ("edge", source, target, weight)   add_edge
#   ("remove", source, target)         remove_edge
#   ("storage", selection)             configure_storage
Operation = tuple


def generate_sequence(seed: int, directed: bool) -> list[Operation]:
    """A fixed 60-step mix of edits and switches for one seed/directedness pair.

    Roughly the first third builds structure (including deliberate self-loops, zero weights and
    duplicate pairs), the middle interleaves edits with backend switches, and the tail exercises
    removals and same-shape weight overwrites. ``configure_storage`` is its own operation, so the
    reference replays it too and its returned selection report is compared at the same step.
    """
    rng = SeededChoices(seed * 2 + (1 if directed else 0) * 7919)
    operations: list[Operation] = []
    for step in range(60):
        if step < 14:
            kind = rng.choice(("node", "edge", "edge", "edge", "remove"))
        elif step < 40:
            kind = rng.choice(("node", "edge", "edge", "remove", "storage", "storage"))
        else:
            kind = rng.choice(("edge", "edge", "remove", "remove", "storage"))
        if kind == "node":
            operations.append(("node", rng.choice(NODE_NAMES)))
        elif kind == "edge":
            source = rng.choice(NODE_NAMES)
            target = rng.choice(NODE_NAMES)
            # Bias the first edges so the small alphabet reliably produces self-loops, zero
            # weights and a same-pair rewrite rather than only random distinct pairs.
            if step < 14 and rng.randrange(3) == 0:
                target = source
            weight = rng.choice(WEIGHT_CHOICES)
            operations.append(("edge", source, target, weight))
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES), rng.choice(NODE_NAMES)))
        else:
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
    # A fixed tail guarantees the required scenarios appear in every seed, in the same positions:
    # an isolated node, a zero-weight self-loop, a duplicate overwrite and a missing-edge removal.
    operations.extend(
        [
            ("node", "iso"),
            ("edge", "z", "z", 0.0),
            ("edge", "a", "b", 8.0 if directed else 8.0),
            ("edge", "a", "b", 2.5),  # same shape, new weight: arrays must rebuild
            ("remove", "iso", "z"),  # never existed: False on every backend
            ("storage", "csr"),
            ("storage", "dense"),
            ("storage", "csr"),  # consecutive materialised switches
            ("edge", "d", "e", 0.0),  # edit after the switches
            ("remove", "d", "e"),
            ("storage", "auto"),
            ("node", "iso"),  # adding an existing node is a no-op success
        ]
    )
    return operations


def generate_switch_heavy_sequence(seed: int, directed: bool) -> list[Operation]:
    """Mostly storage switches with occasional edits: backend state must survive rapid re-selection."""
    rng = SeededChoices(seed * 31 + (3 if directed else 0) * 104729)
    operations: list[Operation] = []
    for _ in range(36):
        kind = rng.choice(("storage", "storage", "storage", "edge", "remove", "node"))
        if kind == "storage":
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
        elif kind == "edge":
            operations.append(("edge", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4]), rng.choice(WEIGHT_CHOICES)))
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4])))
        else:
            operations.append(("node", rng.choice(NODE_NAMES[:4])))
    return operations


def generate_mutation_switch_sequence(seed: int, directed: bool) -> list[Operation]:
    """Edit on one materialised backend, switch to the other, edit, switch back: the classic churn."""
    rng = SeededChoices(seed * 17 + (5 if directed else 0) * 13))
    operations: list[Operation] = [("storage", "csr")]
    for index in range(24):
        source = NODE_NAMES[rng.randrange(5)]
        target = NODE_NAMES[rng.randrange(5)]
        operations.append(("edge", source, target, rng.choice(WEIGHT_CHOICES)))
        operations.append(("storage", "dense" if index % 2 == 0 else "csr"))
        if rng.randrange(3) == 0:
            operations.append(("remove", source, target))
            operations.append(("storage", "auto"))
    return operations


# -- snapshotting ---------------------------------------------------------------------------------
def edge_tuples(graph: Graph) -> list[tuple[str, str, float]]:
    return [(edge.source, edge.target, edge.weight) for edge in graph.edges()]


def neighbors_map(graph: Graph) -> dict[str, list[tuple[str, float]]]:
    return {node: graph.neighbors(node) for node in graph.nodes()}


def read_snapshot(graph: Graph) -> dict[str, object]:
    """Every public read the storage layer sits underneath."""
    nodes = graph.nodes()
    return {
        "nodes": nodes,
        "node_count": graph.node_count,
        "edges": edge_tuples(graph),
        "edge_count": graph.edge_count(),
        "neighbors": neighbors_map(graph),
        "degrees": {node: graph.degree(node) for node in nodes},
        "weighted_degrees": {node: graph.weighted_degree(node) for node in nodes},
        "self_loops": graph.self_loops(),
        "has_negative": graph.has_negative_weights(),
        "csr": graph.csr(),
        "to_document": graph.to_document(),
        "storage_sizes": graph.storage_sizes(),
        "storage_document": graph.storage_document(),
    }


def algorithms_snapshot(graph: Graph) -> dict[str, object]:
    """The complete algorithm surface that is defined for this state.

    Every call is captured as ``(kind, payload)``: a normal result or a raised GraphError's
    document. Whether an answer exists and what evidence it carries must match the baseline too.
    """
    nodes = graph.nodes()
    snap: dict[str, object] = {}
    sources = nodes
    for source in sources:
        results: dict[str, object] = {}
        results["bfs"] = capture(lambda s=source: bfs(graph, s))
        results["dfs"] = capture(lambda s=source: dfs(graph, s))
        results["dijkstra"] = capture(lambda s=source: dijkstra(graph, s))
        results["bellman"] = capture(lambda s=source: bellman_ford(graph, s))
        # A* with an all-zero heuristic: admissible and consistent for every graph, so it must
        # agree with Dijkstra's distance for every target that Dijkstra can reach.
        astar_results: dict[str, object] = {}
        dijkstra_outcome = results["dijkstra"]
        if dijkstra_outcome[0] == "ok":
            distances, previous = dijkstra_outcome[1]
            zero_heuristic = {node: 0.0 for node in nodes}
            paths: dict[str, tuple[str, list[str]]] = {}
            for target in sorted(distances):
                astar_results[target] = capture(
                    lambda s=source, t=target, h=zero_heuristic: astar(graph, s, t, h)
                )
                # Every predecessor map (Dijkstra, Bellman-Ford, A*) must rebuild into a route that
                # walks existing edges and whose weights sum to the reported distance.
                paths[f"dijkstra:{target}"] = (
                    "path",
                    verified_path(graph, previous, source, target, distances[target]),
                )
            bellman_outcome = results["bellman"]
            if bellman_outcome[0] == "ok":
                b_distances, b_previous = bellman_outcome[1]
                for target in sorted(b_distances):
                    paths[f"bellman:{target}"] = (
                        "path",
                        verified_path(graph, b_previous, source, target, b_distances[target]),
                    )
            results["astar"] = astar_results
            results["paths"] = paths
        else:
            results["astar"] = {}
            results["paths"] = {}
        snap[f"source:{source}"] = results
    snap["components"] = capture(components, graph)
    snap["centrality"] = capture(degree_centrality, graph)
    snap["clustering"] = capture(lambda: clustering(graph).to_document())
    snap["pagerank"] = capture(lambda: pagerank(graph).to_document())
    snap["communities"] = capture(lambda: label_propagation(graph).to_document())
    if graph.directed:
        snap["toposort"] = capture(topological_sort, graph)
    return snap


def capture(callable_, *args):
    """Run a zero-argument thunk (or a function with args), returning outcome or error document."""
    try:
        return "ok", callable_(*args)
    except NegativeWeightError as error:
        return "error", ("negative_weight_error", error.to_document())
    except NegativeCycleError as error:
        return "error", ("negative_cycle_error", error.to_document())
    except ValidationError as error:
        return "error", ("validation_error", error.to_document())


def verified_path(graph: Graph, previous, source: str, target: str, distance: float) -> list[str]:
    """Rebuild a predecessor path and prove it is a real route whose weights equal the distance."""
    path = path_from(previous, target)
    if path[0] != source or path[-1] != target:
        raise AssertionError(f"path endpoints mismatch: {path} for {source}->{target}")
    weights = {
        (node, neighbour): weight
        for node in graph.nodes()
        for neighbour, weight in graph.neighbors(node)
    }
    total = 0.0
    for step_source, step_target in zip(path, path[1:]):
        if (step_source, step_target) not in weights:
            raise AssertionError(f"path walks a missing edge: {step_source}->{step_target}")
        total += weights[(step_source, step_target)]
    if total != distance:
        raise AssertionError(f"path weight {total} != distance {distance} along {path}")
    return path


def replay(graph: Graph, operation: Operation):
    kind = operation[0]
    if kind == "node":
        return ("ok", graph.add_node(operation[1]))
    if kind == "edge":
        return ("ok", graph.add_edge(operation[1], operation[2], operation[3]))
    if kind == "remove":
        return ("ok", graph.remove_edge(operation[1], operation[2]))
    if kind == "storage":
        return ("ok", graph.configure_storage(operation[1]))
    raise AssertionError(f"unknown operation kind: {kind}")


# -- the differential harness ---------------------------------------------------------------------
class StateSequenceDifferentialTests(unittest.TestCase):
    def assert_snapshots_equal(self, baseline, candidate, context: str) -> None:
        self.assertEqual(candidate["reads"], baseline["reads"], context)
        self.assertEqual(candidate["algorithms"], baseline["algorithms"], context)

    def run_sequence(self, operations: list[Operation], directed: bool, seed: int, label: str) -> None:
        reference = Graph(directed=directed)
        twins = {backend: Graph(directed=directed) for backend in BACKENDS}

        def twin_snapshot(backend: str) -> dict[str, object]:
            return {
                "reads": read_snapshot(twins[backend]),
                "algorithms": algorithms_snapshot(twins[backend]),
            }

        for index, operation in enumerate(operations):
            context = (
                f"{label} directed={directed} seed={seed} step={index} operation={operation!r}"
            )
            reference_outcome = self.apply_and_capture(reference, operation, "adjacency", context)
            expected = {
                "reads": read_snapshot(reference),
                "algorithms": algorithms_snapshot(reference),
            }
            for backend in BACKENDS:
                twin_context = f"{context} backend={backend}"
                outcome = self.apply_and_capture(twins[backend], operation, backend, twin_context)
                # The operation itself must succeed or fail identically (type and evidence), and a
                # remove must report the same boolean.
                self.assertEqual(outcome, reference_outcome, twin_context)
                snapshot = twin_snapshot(backend)
                self.assertEqual(snapshot["reads"], expected["reads"], twin_context)
                self.assertEqual(snapshot["algorithms"], expected["algorithms"], twin_context)

    def apply_and_capture(self, graph: Graph, operation: Operation, backend: str, context: str):
        """Replay one op, normalising a raised GraphError to its kind plus full evidence."""
        kind = operation[0]
        try:
            if kind == "node":
                graph.add_node(operation[1])
            elif kind == "edge":
                graph.add_edge(operation[1], operation[2], operation[3])
            elif kind == "remove":
                return ("ok", graph.remove_edge(operation[1], operation[2]))
            elif kind == "storage":
                return ("ok", graph.configure_storage(operation[1]))
        except ValidationError as error:
            return ("error", ("validation_error", error.to_document()))
        return ("ok", None)

    # -- main scenarios ---------------------------------------------------------------------------
    def test_mixed_sequences_stay_isomorphic_on_every_backend(self) -> None:
        for directed in (False, True):
            for seed in SEQUENCE_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    operations = generate_sequence(seed, directed)
                    self.run_sequence(operations, directed, seed, "mixed")

    def test_switch_heavy_sequences_stay_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in SWITCH_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(generate_switch_heavy_sequence(seed, directed), directed, seed, "switch-heavy")

    def test_edit_switch_churn_stays_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in MUTATION_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(generate_mutation_switch_sequence(seed, directed), directed, seed, "edit-switch")

    # -- pinned structural scenarios that must appear regardless of generator shape ----------------
    def test_pinned_scenarios_each_keep_all_backends_isomorphic(self) -> None:
        pinned: list[list[Operation]] = [
            # Isolated node only.
            [("node", "a")],
            # Self-loop, undirected mirror included.
            [("edge", "a", "a", 2.0)],
            # Zero-weight edge is distinct from no edge.
            [("edge", "a", "b", 0.0), ("node", "c")],
            # Duplicate edge overwrite.
            [("edge", "a", "b", 9.0), ("edge", "a", "b", 1.0)],
            # Remove an edge that never existed, then add and really remove it.
            [("remove", "x", "y"), ("edge", "x", "y", 1.0), ("remove", "x", "y"), ("remove", "x", "y")],
            # Same-shape weight overwrite after a materialisation.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("edge", "a", "b", 4.0)],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("edge", "a", "b", 4.0)],
            # Edits after a switch, on each materialised backend.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            # Consecutive switches between the materialised backends and auto in both directions.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("storage", "dense"), ("storage", "csr"), ("storage", "dense")],
            [("edge", "a", "b", 1.0), ("storage", "auto"), ("storage", "csr"), ("storage", "auto"), ("storage", "dense")],
            # Negative edges through switches so the negative-aware/negative-refusing split is
            # checked after re-materialisation too.
            [("edge", "a", "b", 1.0), ("edge", "b", "c", -2.0), ("storage", "dense"), ("storage", "csr")],
            # A directed cycle for the toposort branch, and a DAG after breaking it.
            [("edge", "a", "b", 1.0), ("edge", "b", "c", 1.0), ("edge", "c", "a", 1.0), ("storage", "auto")],
            [("edge", "a", "b", 1.0), ("edge", "b", "c", 1.0), ("edge", "a", "c", 1.0), ("storage", "auto")],
        ]
        for directed in (False, True):
            for number, operations in enumerate(pinned):
                with self.subTest(directed=directed, scenario=number):
                    self.run_sequence(operations, directed, number, f"pinned-{number}")

    def test_auto_selection_report_matches_the_formula_at_every_step(self) -> None:
        # The auto report is part of the compared surface already; additionally pin its selected
        # backend against an independent re-derivation so a wrong selection can never masquerade.
        for directed in (False, True):
            for seed in SEQUENCE_SEEDS[:12]:
                graph = Graph(directed=directed)
                for index, operation in enumerate(generate_sequence(seed, directed)):
                    if operation[0] == "storage" and operation[1] == "auto":
                        document = graph.configure_storage("auto")
                        entries, csr_bytes, dense_bytes = graph.storage_sizes()
                        n = graph.node_count
                        expected = "csr" if n == 0 or csr_bytes <= dense_bytes else "dense"
                        if expected == "dense" and dense_bytes > 536870912:
                            expected = "csr"
                        self.assertEqual(document["selected"], expected, (directed, seed, index))
                    elif operation[0] != "storage":
                        self.apply_and_capture(graph, operation, "auto", "")
                    else:
                        graph.configure_storage(operation[1])


class RejectionInvarianceTests(unittest.TestCase):
    """Invalid inputs raise ValidationError and leave the whole observable state untouched."""

    INVALID_EDGE_CALLS = (
        ("", "b", 1.0),
        ("a", "", 1.0),
        ("a", "b", "1.5"),
        ("a", "b", None),
        ("a", "b", True),
        ("a", "b", float("nan")),
        ("a", "b", float("inf")),
        ("a", "b", float("-inf")),
    )

    def snapshot(self, graph: Graph) -> dict[str, object]:
        return {
            "reads": read_snapshot(graph),
            "algorithms": algorithms_snapshot(graph),
            "storage": graph._storage,
            "requested": graph._storage_requested,
        }

    def replay_rejection(self, graph: Graph, call, expected_node_error: bool) -> None:
        with self.assertRaises(ValidationError):
            if expected_node_error:
                graph.add_node(call)
            else:
                graph.add_edge(call[0], call[1], call[2])

    def test_rejected_calls_change_nothing_on_every_backend(self) -> None:
        for directed in (False, True):
            for backend in ALL_SELECTIONS:
                with self.subTest(directed=directed, backend=backend):
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 2.0)
                    graph.add_edge("b", "c", 0.0)
                    graph.add_edge("a", "a", 3.0)
                    graph.add_node("iso")
                    graph.configure_storage(backend)
                    before = self.snapshot(graph)
                    for call in self.INVALID_EDGE_CALLS:
                        self.replay_rejection(graph, call, expected_node_error=False)
                    with self.assertRaises(ValidationError):
                        graph.add_node("")
                    # Nodes, edges, the active/requested storage selection and every algorithm
                    # result are exactly what they were before the rejected calls.
                    self.assertEqual(self.snapshot(graph), before)

    def test_rejection_evidence_is_identical_across_backends(self) -> None:
        for directed in (False, True):
            for call in self.INVALID_EDGE_CALLS:
                documents = {}
                for backend in ALL_SELECTIONS:
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 1.0)
                    graph.configure_storage(backend)
                    with self.assertRaises(ValidationError) as caught:
                        graph.add_edge(call[0], call[1], call[2])
                    documents[backend] = caught.exception.to_document()
                self.assertEqual(documents["csr"], documents["adjacency"], (directed, call))
                self.assertEqual(documents["dense"], documents["adjacency"], (directed, call))
                self.assertEqual(documents["auto"], documents["adjacency"], (directed, call))

    def test_remove_missing_edge_returns_false_on_every_backend(self) -> None:
        for directed in (False, True):
            for backend in ALL_SELECTIONS:
                with self.subTest(directed=directed, backend=backend):
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 1.0)
                    graph.add_node("iso")
                    graph.configure_storage(backend)
                    # Neither endpoint / one endpoint missing / pair present but no such edge.
                    for source, target in (("x", "y"), ("a", "x"), ("iso", "b"), ("b", "a")):
                        if (source, target) == ("b", "a") and not directed:
                            continue  # that edge does exist in the undirected graph
                        self.assertFalse(
                            graph.remove_edge(source, target),
                            (backend, source, target),
                        )
                    if directed:
                        self.assertFalse(graph.remove_edge("b", "a"))  # reverse arc absent
                    # The failed removals changed nothing.
                    self.assertEqual(edge_tuples(graph), [("a", "b", 1.0)] if directed else [("a", "b", 1.0)])
                    self.assertEqual(graph.node_count, 3)

    def test_invalid_weight_types_are_all_validation_errors(self) -> None:
        # Belt-and-braces enumeration matching the shared validation contract.
        for weight in INVALID_WEIGHTS:
            for directed in (False, True):
                graph = Graph(directed=directed)
                graph.configure_storage("auto")
                with self.subTest(weight=weight, directed=directed):
                    with self.assertRaises(ValidationError):
                        graph.add_edge("a", "b", weight)
                self.assertEqual(graph.nodes(), [])
                self.assertEqual(graph.edge_count(), 0)

    def test_nan_and_friends_are_non_finite_not_silently_stored(self) -> None:
        graph = Graph(directed=True)
        for value in (float("nan"), float("inf"), float("-inf")):
            with self.assertRaises(ValidationError):
                graph.add_edge("a", "b", value)
        self.assertTrue(math.isfinite(weight) for _ in [0])  # sanity import stays used
        self.assertEqual(graph.edges(), [])


if __name__ == "__main__":
    unittest.main()

toolUseResult.content:
"""Repeatable state-sequence differential tests across the storage backends.

One graph always stays on the mutable ``adjacency`` dict and is the isomorphism reference; three
twins replay the *exact* same fixed operation sequence on ``csr``, ``dense`` and ``auto``. After
every successful step the public observation surface is compared -- nodes, edges, neighbours,
degree, edge count, self loops, the CSR export, ``to_document``, storage footprints and the
selection report -- and, whenever the state's preconditions hold, the complete results of every
algorithm (BFS, DFS, Dijkstra, Bellman-Ford, components, centrality, clustering, PageRank, label
propagation; topological sort for directed acyclic states; A* with an all-zero heuristic for
reachable targets), plus a re-walk of every ``path_from`` reconstruction. The exception type and
evidence of identical calls must also agree across backends.

The sequences come from a tiny seeded integer generator (no third-party property library, no
clock or environment input): the same seeds always pick the same cases, and a failure names the
graph type, backend, seed and the first inconsistent step. The scenarios stably cover isolated
nodes, self-loops, zero-weight edges, duplicate overwrites, removing a missing edge, edits after
a switch, same-shape weight overwrites, and repeated switches between the materialised backends.
Empty node names and non-finite/non-numeric weights keep raising ``ValidationError`` and must
change neither nodes, edges, storage selection nor subsequent algorithm results; removing a
missing edge keeps returning ``False``.
"""

from __future__ import annotations

import math
import unittest

from graphtk import (
    Graph,
    NegativeCycleError,
    NegativeWeightError,
    ValidationError,
    astar,
    bellman_ford,
    bfs,
    clustering,
    components,
    degree_centrality,
    dfs,
    dijkstra,
    label_propagation,
    path_from,
    pagerank,
    topological_sort,
)

# Seeds are fixed lists: adding or removing a seed is an explicit, reviewable choice, never a
# random draw, so two runs of this file execute byte-for-byte identical cases.
SEQUENCE_SEEDS = list(range(40))
SWITCH_SEEDS = list(range(8))
MUTATION_SEEDS = list(range(10))
BACKENDS = ("csr", "dense", "auto")
ALL_SELECTIONS = ("adjacency", "csr", "dense", "auto")
NODE_NAMES = ("a", "b", "c", "d", "e", "f")

# Finite numbers only: a generated state never approaches the 512 MiB dense ceiling (n <= 6).
WEIGHT_CHOICES = (0, 0.0, 1, 2, -2, 3, -1, 4, 0, 1, 5, -3)

# Rejected by _validated_weight / add_node exactly the way the public API rejects them.
INVALID_WEIGHTS = (True, False, "1.5", None, float("nan"), float("inf"), float("-inf"))
INVALID_NAMES = ("",)


class SeededChoices:
    """Deterministic integer stream in the spirit of ``random.Random`` -- seeded, nothing else.

    Only ``randrange`` and ``choice`` are needed; a hand-rolled LCG keeps the case selection
    independent of hashing, process seeding and the wall clock.
    """

    __slots__ = ("state",)

    def __init__(self, seed: int) -> None:
        self.state = seed & 0xFFFFFFFF

    def randrange(self, stop: int) -> int:
        # Constants from Numerical Recipes; the low bits of an LCG are weak, so the next value is
        # taken from the high half.
        self.state = (1664525 * self.state + 1013904223) & 0xFFFFFFFF
        return (self.state >> 16) % stop

    def choice(self, options):
        return options[self.randrange(len(options))]


# -- operation records ----------------------------------------------------------------------------
# Every record is a tuple so a replayed step is trivially reproducible in a failure message:
#   ("node", name)                     add_node
#   ("edge", source, target, weight)   add_edge
#   ("remove", source, target)         remove_edge
#   ("storage", selection)             configure_storage
Operation = tuple


def generate_sequence(seed: int, directed: bool) -> list[Operation]:
    """A fixed 60-step mix of edits and switches for one seed/directedness pair.

    Roughly the first third builds structure (including deliberate self-loops, zero weights and
    duplicate pairs), the middle interleaves edits with backend switches, and the tail exercises
    removals and same-shape weight overwrites. ``configure_storage`` is its own operation, so the
    reference replays it too and its returned selection report is compared at the same step.
    """
    rng = SeededChoices(seed * 2 + (1 if directed else 0) * 7919)
    operations: list[Operation] = []
    for step in range(60):
        if step < 14:
            kind = rng.choice(("node", "edge", "edge", "edge", "remove"))
        elif step < 40:
            kind = rng.choice(("node", "edge", "edge", "remove", "storage", "storage"))
        else:
            kind = rng.choice(("edge", "edge", "remove", "remove", "storage"))
        if kind == "node":
            operations.append(("node", rng.choice(NODE_NAMES)))
        elif kind == "edge":
            source = rng.choice(NODE_NAMES)
            target = rng.choice(NODE_NAMES)
            # Bias the first edges so the small alphabet reliably produces self-loops, zero
            # weights and a same-pair rewrite rather than only random distinct pairs.
            if step < 14 and rng.randrange(3) == 0:
                target = source
            weight = rng.choice(WEIGHT_CHOICES)
            operations.append(("edge", source, target, weight))
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES), rng.choice(NODE_NAMES)))
        else:
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
    # A fixed tail guarantees the required scenarios appear in every seed, in the same positions:
    # an isolated node, a zero-weight self-loop, a duplicate overwrite and a missing-edge removal.
    operations.extend(
        [
            ("node", "iso"),
            ("edge", "z", "z", 0.0),
            ("edge", "a", "b", 8.0 if directed else 8.0),
            ("edge", "a", "b", 2.5),  # same shape, new weight: arrays must rebuild
            ("remove", "iso", "z"),  # never existed: False on every backend
            ("storage", "csr"),
            ("storage", "dense"),
            ("storage", "csr"),  # consecutive materialised switches
            ("edge", "d", "e", 0.0),  # edit after the switches
            ("remove", "d", "e"),
            ("storage", "auto"),
            ("node", "iso"),  # adding an existing node is a no-op success
        ]
    )
    return operations


def generate_switch_heavy_sequence(seed: int, directed: bool) -> list[Operation]:
    """Mostly storage switches with occasional edits: backend state must survive rapid re-selection."""
    rng = SeededChoices(seed * 31 + (3 if directed else 0) * 104729)
    operations: list[Operation] = []
    for _ in range(36):
        kind = rng.choice(("storage", "storage", "storage", "edge", "remove", "node"))
        if kind == "storage":
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
        elif kind == "edge":
            operations.append(("edge", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4]), rng.choice(WEIGHT_CHOICES)))
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4])))
        else:
            operations.append(("node", rng.choice(NODE_NAMES[:4])))
    return operations


def generate_mutation_switch_sequence(seed: int, directed: bool) -> list[Operation]:
    """Edit on one materialised backend, switch to the other, edit, switch back: the classic churn."""
    rng = SeededChoices(seed * 17 + (5 if directed else 0) * 13))
    operations: list[Operation] = [("storage", "csr")]
    for index in range(24):
        source = NODE_NAMES[rng.randrange(5)]
        target = NODE_NAMES[rng.randrange(5)]
        operations.append(("edge", source, target, rng.choice(WEIGHT_CHOICES)))
        operations.append(("storage", "dense" if index % 2 == 0 else "csr"))
        if rng.randrange(3) == 0:
            operations.append(("remove", source, target))
            operations.append(("storage", "auto"))
    return operations


# -- snapshotting ---------------------------------------------------------------------------------
def edge_tuples(graph: Graph) -> list[tuple[str, str, float]]:
    return [(edge.source, edge.target, edge.weight) for edge in graph.edges()]


def neighbors_map(graph: Graph) -> dict[str, list[tuple[str, float]]]:
    return {node: graph.neighbors(node) for node in graph.nodes()}


def read_snapshot(graph: Graph) -> dict[str, object]:
    """Every public read the storage layer sits underneath."""
    nodes = graph.nodes()
    return {
        "nodes": nodes,
        "node_count": graph.node_count,
        "edges": edge_tuples(graph),
        "edge_count": graph.edge_count(),
        "neighbors": neighbors_map(graph),
        "degrees": {node: graph.degree(node) for node in nodes},
        "weighted_degrees": {node: graph.weighted_degree(node) for node in nodes},
        "self_loops": graph.self_loops(),
        "has_negative": graph.has_negative_weights(),
        "csr": graph.csr(),
        "to_document": graph.to_document(),
        "storage_sizes": graph.storage_sizes(),
        "storage_document": graph.storage_document(),
    }


def algorithms_snapshot(graph: Graph) -> dict[str, object]:
    """The complete algorithm surface that is defined for this state.

    Every call is captured as ``(kind, payload)``: a normal result or a raised GraphError's
    document. Whether an answer exists and what evidence it carries must match the baseline too.
    """
    nodes = graph.nodes()
    snap: dict[str, object] = {}
    sources = nodes
    for source in sources:
        results: dict[str, object] = {}
        results["bfs"] = capture(lambda s=source: bfs(graph, s))
        results["dfs"] = capture(lambda s=source: dfs(graph, s))
        results["dijkstra"] = capture(lambda s=source: dijkstra(graph, s))
        results["bellman"] = capture(lambda s=source: bellman_ford(graph, s))
        # A* with an all-zero heuristic: admissible and consistent for every graph, so it must
        # agree with Dijkstra's distance for every target that Dijkstra can reach.
        astar_results: dict[str, object] = {}
        dijkstra_outcome = results["dijkstra"]
        if dijkstra_outcome[0] == "ok":
            distances, previous = dijkstra_outcome[1]
            zero_heuristic = {node: 0.0 for node in nodes}
            paths: dict[str, tuple[str, list[str]]] = {}
            for target in sorted(distances):
                astar_results[target] = capture(
                    lambda s=source, t=target, h=zero_heuristic: astar(graph, s, t, h)
                )
                # Every predecessor map (Dijkstra, Bellman-Ford, A*) must rebuild into a route that
                # walks existing edges and whose weights sum to the reported distance.
                paths[f"dijkstra:{target}"] = (
                    "path",
                    verified_path(graph, previous, source, target, distances[target]),
                )
            bellman_outcome = results["bellman"]
            if bellman_outcome[0] == "ok":
                b_distances, b_previous = bellman_outcome[1]
                for target in sorted(b_distances):
                    paths[f"bellman:{target}"] = (
                        "path",
                        verified_path(graph, b_previous, source, target, b_distances[target]),
                    )
            results["astar"] = astar_results
            results["paths"] = paths
        else:
            results["astar"] = {}
            results["paths"] = {}
        snap[f"source:{source}"] = results
    snap["components"] = capture(components, graph)
    snap["centrality"] = capture(degree_centrality, graph)
    snap["clustering"] = capture(lambda: clustering(graph).to_document())
    snap["pagerank"] = capture(lambda: pagerank(graph).to_document())
    snap["communities"] = capture(lambda: label_propagation(graph).to_document())
    if graph.directed:
        snap["toposort"] = capture(topological_sort, graph)
    return snap


def capture(callable_, *args):
    """Run a zero-argument thunk (or a function with args), returning outcome or error document."""
    try:
        return "ok", callable_(*args)
    except NegativeWeightError as error:
        return "error", ("negative_weight_error", error.to_document())
    except NegativeCycleError as error:
        return "error", ("negative_cycle_error", error.to_document())
    except ValidationError as error:
        return "error", ("validation_error", error.to_document())


def verified_path(graph: Graph, previous, source: str, target: str, distance: float) -> list[str]:
    """Rebuild a predecessor path and prove it is a real route whose weights equal the distance."""
    path = path_from(previous, target)
    if path[0] != source or path[-1] != target:
        raise AssertionError(f"path endpoints mismatch: {path} for {source}->{target}")
    weights = {
        (node, neighbour): weight
        for node in graph.nodes()
        for neighbour, weight in graph.neighbors(node)
    }
    total = 0.0
    for step_source, step_target in zip(path, path[1:]):
        if (step_source, step_target) not in weights:
            raise AssertionError(f"path walks a missing edge: {step_source}->{step_target}")
        total += weights[(step_source, step_target)]
    if total != distance:
        raise AssertionError(f"path weight {total} != distance {distance} along {path}")
    return path


def replay(graph: Graph, operation: Operation):
    kind = operation[0]
    if kind == "node":
        return ("ok", graph.add_node(operation[1]))
    if kind == "edge":
        return ("ok", graph.add_edge(operation[1], operation[2], operation[3]))
    if kind == "remove":
        return ("ok", graph.remove_edge(operation[1], operation[2]))
    if kind == "storage":
        return ("ok", graph.configure_storage(operation[1]))
    raise AssertionError(f"unknown operation kind: {kind}")


# -- the differential harness ---------------------------------------------------------------------
class StateSequenceDifferentialTests(unittest.TestCase):
    def assert_snapshots_equal(self, baseline, candidate, context: str) -> None:
        self.assertEqual(candidate["reads"], baseline["reads"], context)
        self.assertEqual(candidate["algorithms"], baseline["algorithms"], context)

    def run_sequence(self, operations: list[Operation], directed: bool, seed: int, label: str) -> None:
        reference = Graph(directed=directed)
        twins = {backend: Graph(directed=directed) for backend in BACKENDS}

        def twin_snapshot(backend: str) -> dict[str, object]:
            return {
                "reads": read_snapshot(twins[backend]),
                "algorithms": algorithms_snapshot(twins[backend]),
            }

        for index, operation in enumerate(operations):
            context = (
                f"{label} directed={directed} seed={seed} step={index} operation={operation!r}"
            )
            reference_outcome = self.apply_and_capture(reference, operation, "adjacency", context)
            expected = {
                "reads": read_snapshot(reference),
                "algorithms": algorithms_snapshot(reference),
            }
            for backend in BACKENDS:
                twin_context = f"{context} backend={backend}"
                outcome = self.apply_and_capture(twins[backend], operation, backend, twin_context)
                # The operation itself must succeed or fail identically (type and evidence), and a
                # remove must report the same boolean.
                self.assertEqual(outcome, reference_outcome, twin_context)
                snapshot = twin_snapshot(backend)
                self.assertEqual(snapshot["reads"], expected["reads"], twin_context)
                self.assertEqual(snapshot["algorithms"], expected["algorithms"], twin_context)

    def apply_and_capture(self, graph: Graph, operation: Operation, backend: str, context: str):
        """Replay one op, normalising a raised GraphError to its kind plus full evidence."""
        kind = operation[0]
        try:
            if kind == "node":
                graph.add_node(operation[1])
            elif kind == "edge":
                graph.add_edge(operation[1], operation[2], operation[3])
            elif kind == "remove":
                return ("ok", graph.remove_edge(operation[1], operation[2]))
            elif kind == "storage":
                return ("ok", graph.configure_storage(operation[1]))
        except ValidationError as error:
            return ("error", ("validation_error", error.to_document()))
        return ("ok", None)

    # -- main scenarios ---------------------------------------------------------------------------
    def test_mixed_sequences_stay_isomorphic_on_every_backend(self) -> None:
        for directed in (False, True):
            for seed in SEQUENCE_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    operations = generate_sequence(seed, directed)
                    self.run_sequence(operations, directed, seed, "mixed")

    def test_switch_heavy_sequences_stay_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in SWITCH_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(generate_switch_heavy_sequence(seed, directed), directed, seed, "switch-heavy")

    def test_edit_switch_churn_stays_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in MUTATION_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(generate_mutation_switch_sequence(seed, directed), directed, seed, "edit-switch")

    # -- pinned structural scenarios that must appear regardless of generator shape ----------------
    def test_pinned_scenarios_each_keep_all_backends_isomorphic(self) -> None:
        pinned: list[list[Operation]] = [
            # Isolated node only.
            [("node", "a")],
            # Self-loop, undirected mirror included.
            [("edge", "a", "a", 2.0)],
            # Zero-weight edge is distinct from no edge.
            [("edge", "a", "b", 0.0), ("node", "c")],
            # Duplicate edge overwrite.
            [("edge", "a", "b", 9.0), ("edge", "a", "b", 1.0)],
            # Remove an edge that never existed, then add and really remove it.
            [("remove", "x", "y"), ("edge", "x", "y", 1.0), ("remove", "x", "y"), ("remove", "x", "y")],
            # Same-shape weight overwrite after a materialisation.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("edge", "a", "b", 4.0)],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("edge", "a", "b", 4.0)],
            # Edits after a switch, on each materialised backend.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            # Consecutive switches between the materialised backends and auto in both directions.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("storage", "dense"), ("storage", "csr"), ("storage", "dense")],
            [("edge", "a", "b", 1.0), ("storage", "auto"), ("storage", "csr"), ("storage", "auto"), ("storage", "dense")],
            # Negative edges through switches so the negative-aware/negative-refusing split is
            # checked after re-materialisation too.
            [("edge", "a", "b", 1.0), ("edge", "b", "c", -2.0), ("storage", "dense"), ("storage", "csr")],
            # A directed cycle for the toposort branch, and a DAG after breaking it.
            [("edge", "a", "b", 1.0), ("edge", "b", "c", 1.0), ("edge", "c", "a", 1.0), ("storage", "auto")],
            [("edge", "a", "b", 1.0), ("edge", "b", "c", 1.0), ("edge", "a", "c", 1.0), ("storage", "auto")],
        ]
        for directed in (False, True):
            for number, operations in enumerate(pinned):
                with self.subTest(directed=directed, scenario=number):
                    self.run_sequence(operations, directed, number, f"pinned-{number}")

    def test_auto_selection_report_matches_the_formula_at_every_step(self) -> None:
        # The auto report is part of the compared surface already; additionally pin its selected
        # backend against an independent re-derivation so a wrong selection can never masquerade.
        for directed in (False, True):
            for seed in SEQUENCE_SEEDS[:12]:
                graph = Graph(directed=directed)
                for index, operation in enumerate(generate_sequence(seed, directed)):
                    if operation[0] == "storage" and operation[1] == "auto":
                        document = graph.configure_storage("auto")
                        entries, csr_bytes, dense_bytes = graph.storage_sizes()
                        n = graph.node_count
                        expected = "csr" if n == 0 or csr_bytes <= dense_bytes else "dense"
                        if expected == "dense" and dense_bytes > 536870912:
                            expected = "csr"
                        self.assertEqual(document["selected"], expected, (directed, seed, index))
                    elif operation[0] != "storage":
                        self.apply_and_capture(graph, operation, "auto", "")
                    else:
                        graph.configure_storage(operation[1])


class RejectionInvarianceTests(unittest.TestCase):
    """Invalid inputs raise ValidationError and leave the whole observable state untouched."""

    INVALID_EDGE_CALLS = (
        ("", "b", 1.0),
        ("a", "", 1.0),
        ("a", "b", "1.5"),
        ("a", "b", None),
        ("a", "b", True),
        ("a", "b", float("nan")),
        ("a", "b", float("inf")),
        ("a", "b", float("-inf")),
    )

    def snapshot(self, graph: Graph) -> dict[str, object]:
        return {
            "reads": read_snapshot(graph),
            "algorithms": algorithms_snapshot(graph),
            "storage": graph._storage,
            "requested": graph._storage_requested,
        }

    def replay_rejection(self, graph: Graph, call, expected_node_error: bool) -> None:
        with self.assertRaises(ValidationError):
            if expected_node_error:
                graph.add_node(call)
            else:
                graph.add_edge(call[0], call[1], call[2])

    def test_rejected_calls_change_nothing_on_every_backend(self) -> None:
        for directed in (False, True):
            for backend in ALL_SELECTIONS:
                with self.subTest(directed=directed, backend=backend):
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 2.0)
                    graph.add_edge("b", "c", 0.0)
                    graph.add_edge("a", "a", 3.0)
                    graph.add_node("iso")
                    graph.configure_storage(backend)
                    before = self.snapshot(graph)
                    for call in self.INVALID_EDGE_CALLS:
                        self.replay_rejection(graph, call, expected_node_error=False)
                    with self.assertRaises(ValidationError):
                        graph.add_node("")
                    # Nodes, edges, the active/requested storage selection and every algorithm
                    # result are exactly what they were before the rejected calls.
                    self.assertEqual(self.snapshot(graph), before)

    def test_rejection_evidence_is_identical_across_backends(self) -> None:
        for directed in (False, True):
            for call in self.INVALID_EDGE_CALLS:
                documents = {}
                for backend in ALL_SELECTIONS:
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 1.0)
                    graph.configure_storage(backend)
                    with self.assertRaises(ValidationError) as caught:
                        graph.add_edge(call[0], call[1], call[2])
                    documents[backend] = caught.exception.to_document()
                self.assertEqual(documents["csr"], documents["adjacency"], (directed, call))
                self.assertEqual(documents["dense"], documents["adjacency"], (directed, call))
                self.assertEqual(documents["auto"], documents["adjacency"], (directed, call))

    def test_remove_missing_edge_returns_false_on_every_backend(self) -> None:
        for directed in (False, True):
            for backend in ALL_SELECTIONS:
                with self.subTest(directed=directed, backend=backend):
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 1.0)
                    graph.add_node("iso")
                    graph.configure_storage(backend)
                    # Neither endpoint / one endpoint missing / pair present but no such edge.
                    for source, target in (("x", "y"), ("a", "x"), ("iso", "b"), ("b", "a")):
                        if (source, target) == ("b", "a") and not directed:
                            continue  # that edge does exist in the undirected graph
                        self.assertFalse(
                            graph.remove_edge(source, target),
                            (backend, source, target),
                        )
                    if directed:
                        self.assertFalse(graph.remove_edge("b", "a"))  # reverse arc absent
                    # The failed removals changed nothing.
                    self.assertEqual(edge_tuples(graph), [("a", "b", 1.0)] if directed else [("a", "b", 1.0)])
                    self.assertEqual(graph.node_count, 3)

    def test_invalid_weight_types_are_all_validation_errors(self) -> None:
        # Belt-and-braces enumeration matching the shared validation contract.
        for weight in INVALID_WEIGHTS:
            for directed in (False, True):
                graph = Graph(directed=directed)
                graph.configure_storage("auto")
                with self.subTest(weight=weight, directed=directed):
                    with self.assertRaises(ValidationError):
                        graph.add_edge("a", "b", weight)
                self.assertEqual(graph.nodes(), [])
                self.assertEqual(graph.edge_count(), 0)

    def test_nan_and_friends_are_non_finite_not_silently_stored(self) -> None:
        graph = Graph(directed=True)
        for value in (float("nan"), float("inf"), float("-inf")):
            with self.assertRaises(ValidationError):
                graph.add_edge("a", "b", value)
        self.assertTrue(math.isfinite(weight) for _ in [0])  # sanity import stays used
        self.assertEqual(graph.edges(), [])


if __name__ == "__main__":
    unittest.main()

input.content:
"""Repeatable state-sequence differential tests across the storage backends.

One graph always stays on the mutable ``adjacency`` dict and is the isomorphism reference; three
twins replay the *exact* same fixed operation sequence on ``csr``, ``dense`` and ``auto``. After
every successful step the public observation surface is compared -- nodes, edges, neighbours,
degree, edge count, self loops, the CSR export, ``to_document``, storage footprints and the
selection report -- and, whenever the state's preconditions hold, the complete results of every
algorithm (BFS, DFS, Dijkstra, Bellman-Ford, components, centrality, clustering, PageRank, label
propagation; topological sort for directed states; A* with an all-zero heuristic for reachable
targets), plus a re-walk of every ``path_from`` reconstruction. The exception type and evidence of
identical calls must also agree across backends.

The sequences come from a tiny seeded integer generator (no third-party property library, no
clock or environment input): the same seeds always pick the same cases, and a failure names the
graph type, backend, seed and the first inconsistent step. The scenarios stably cover isolated
nodes, self-loops, zero-weight edges, duplicate overwrites, removing a missing edge, edits after
a switch, same-shape weight overwrites, and repeated switches between the materialised backends.
Empty node names and non-finite/non-numeric weights keep raising ``ValidationError`` and must
change neither nodes, edges, storage selection nor subsequent algorithm results; removing a
missing edge keeps returning ``False``.
"""

from __future__ import annotations

import unittest

from graphtk import (
    Graph,
    NegativeCycleError,
    NegativeWeightError,
    ValidationError,
    astar,
    bellman_ford,
    bfs,
    clustering,
    components,
    degree_centrality,
    dfs,
    dijkstra,
    label_propagation,
    path_from,
    pagerank,
    topological_sort,
)
from graphtk.graph import DENSE_LIMIT_BYTES

# Seeds are fixed lists: adding or removing a seed is an explicit, reviewable choice, never a
# random draw, so two runs of this file execute byte-for-byte identical cases.
SEQUENCE_SEEDS = list(range(12))
SWITCH_SEEDS = list(range(6))
MUTATION_SEEDS = list(range(6))
BACKENDS = ("csr", "dense", "auto")
ALL_SELECTIONS = ("adjacency", "csr", "dense", "auto")
NODE_NAMES = ("a", "b", "c", "d", "e", "f")

# Finite numbers only: a generated state never approaches the 512 MiB dense ceiling (n <= 8).
WEIGHT_CHOICES = (0, 0.0, 1, 2, -2, 3, -1, 4, 0, 1, 5, -3, 2.5)

# Rejected by _validated_weight / add_node exactly the way the public API rejects them.
INVALID_WEIGHTS = (True, False, "1.5", None, float("nan"), float("inf"), float("-inf"))

# Backend-neutral keys of the storage report; requested/selected/logicalBytes are checked against
# the operation and the footprint formula instead.
NEUTRAL_STORAGE_KEYS = ("adjacencyEntries", "csrBytes", "denseBytes", "density")


class SeededChoices:
    """Deterministic integer stream -- a seeded LCG, nothing read from the clock or environment.

    Only ``randrange`` and ``choice`` are needed; the hand-rolled stream keeps case selection
    independent of hash randomisation, process seeding and the wall clock.
    """

    __slots__ = ("state",)

    def __init__(self, seed: int) -> None:
        self.state = seed & 0xFFFFFFFF

    def randrange(self, stop: int) -> int:
        # Numerical Recipes constants; LCG low bits are weak, so consume the high half.
        self.state = (1664525 * self.state + 1013904223) & 0xFFFFFFFF
        return (self.state >> 16) % stop

    def choice(self, options):
        return options[self.randrange(len(options))]


# -- operation records ----------------------------------------------------------------------------
# Every record is a tuple so a replayed step is trivially reproducible in a failure message:
#   ("node", name)                     add_node
#   ("edge", source, target, weight)   add_edge
#   ("remove", source, target)         remove_edge -> bool
#   ("storage", selection)             configure_storage -> storage document
Operation = tuple


def generate_sequence(seed: int, directed: bool) -> list[Operation]:
    """A fixed 48-step mix of edits and switches for one seed/directedness pair.

    The opening builds structure (self-loops, zero weights and duplicate pairs are biased in), the
    middle interleaves edits with backend switches, the tail stresses removals. A fixed tail then
    guarantees the required scenarios occur in every seed at the same positions.
    """
    rng = SeededChoices(seed * 2 + (1 if directed else 0) * 7919)
    operations: list[Operation] = []
    for step in range(48):
        if step < 14:
            kind = rng.choice(("node", "edge", "edge", "edge", "remove"))
        elif step < 34:
            kind = rng.choice(("node", "edge", "edge", "remove", "storage", "storage"))
        else:
            kind = rng.choice(("edge", "edge", "remove", "remove", "storage"))
        if kind == "node":
            operations.append(("node", rng.choice(NODE_NAMES)))
        elif kind == "edge":
            source = rng.choice(NODE_NAMES)
            target = rng.choice(NODE_NAMES)
            if step < 14 and rng.randrange(3) == 0:
                target = source  # reliably create self-loops in the opening
            operations.append(("edge", source, target, rng.choice(WEIGHT_CHOICES)))
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES), rng.choice(NODE_NAMES)))
        else:
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
    # Fixed tail: the mandated scenarios appear in every sequence, at identical positions.
    operations.extend(
        [
            ("node", "iso"),  # isolated node
            ("edge", "z", "z", 0.0),  # zero-weight self-loop on a fresh node
            ("edge", "a", "b", 8.0),
            ("edge", "a", "b", 2.5),  # same shape, new weight: arrays must rebuild
            ("remove", "iso", "z"),  # never an edge: False on every backend
            ("storage", "csr"),
            ("storage", "dense"),
            ("storage", "csr"),  # consecutive switches between materialised backends
            ("edge", "d", "e", 0.0),  # edit after the switches
            ("remove", "d", "e"),
            ("storage", "auto"),
            ("node", "iso"),  # re-adding an existing node is a no-op success
        ]
    )
    return operations


def generate_switch_heavy_sequence(seed: int, directed: bool) -> list[Operation]:
    """Mostly storage switches with occasional edits: backend state survives rapid re-selection."""
    rng = SeededChoices(seed * 31 + (3 if directed else 0) * 104729)
    operations: list[Operation] = []
    for _ in range(36):
        kind = rng.choice(("storage", "storage", "storage", "edge", "remove", "node"))
        if kind == "storage":
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
        elif kind == "edge":
            operations.append(
                ("edge", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4]), rng.choice(WEIGHT_CHOICES))
            )
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4])))
        else:
            operations.append(("node", rng.choice(NODE_NAMES[:4])))
    return operations


def generate_mutation_switch_sequence(seed: int, directed: bool) -> list[Operation]:
    """Edit on one materialised backend, switch to the other, edit, switch back: classic churn."""
    rng = SeededChoices(seed * 17 + (5 if directed else 0) * 13)
    operations: list[Operation] = [("storage", "csr")]
    for index in range(20):
        source = NODE_NAMES[rng.randrange(5)]
        target = NODE_NAMES[rng.randrange(5)]
        operations.append(("edge", source, target, rng.choice(WEIGHT_CHOICES)))
        operations.append(("storage", "dense" if index % 2 == 0 else "csr"))
        if rng.randrange(3) == 0:
            operations.append(("remove", source, target))
            operations.append(("storage", "auto"))
    return operations


# -- snapshotting ---------------------------------------------------------------------------------
def edge_tuples(graph: Graph) -> list[tuple[str, str, float]]:
    return [(edge.source, edge.target, edge.weight) for edge in graph.edges()]


def neutral_storage_report(graph: Graph) -> dict[str, object]:
    document = graph.storage_document()
    return {key: document[key] for key in NEUTRAL_STORAGE_KEYS}


def expected_selection(requested: str, n: int, csr_bytes: int, dense_bytes: int) -> str:
    """Independent re-derivation of configure_storage's resolution rule."""
    if requested != "auto":
        return requested
    selected = "csr" if n == 0 or csr_bytes <= dense_bytes else "dense"
    if selected == "dense" and dense_bytes > DENSE_LIMIT_BYTES:
        selected = "csr"
    return selected


def read_snapshot(graph: Graph) -> dict[str, object]:
    """Every public read the storage layer sits underneath (README-committed fields only)."""
    nodes = graph.nodes()
    return {
        "nodes": nodes,
        "node_count": graph.node_count,
        "edges": edge_tuples(graph),
        "edge_count": graph.edge_count(),
        "neighbors": {node: graph.neighbors(node) for node in nodes},
        "degrees": {node: graph.degree(node) for node in nodes},
        "self_loops": graph.self_loops(),
        "csr": graph.csr(),
        "to_document": graph.to_document(),
        "storage_sizes": graph.storage_sizes(),
        "storage_report": neutral_storage_report(graph),
    }


def capture(thunk):
    """Run a thunk, returning ``('ok', value)`` or ``('error', (kind, full_document))``."""
    try:
        return "ok", thunk()
    except NegativeWeightError as error:
        return "error", ("negative_weight_error", error.to_document())
    except NegativeCycleError as error:
        return "error", ("negative_cycle_error", error.to_document())
    except ValidationError as error:
        return "error", ("validation_error", error.to_document())


def verified_path(graph: Graph, previous, source: str, target: str, distance: float) -> list[str]:
    """Rebuild a predecessor path and prove it walks existing edges and sums to the distance."""
    path = path_from(previous, target)
    if path[0] != source or path[-1] != target:
        raise AssertionError(f"path endpoints mismatch: {path} for {source}->{target}")
    weights = {
        (node, neighbour): weight
        for node in graph.nodes()
        for neighbour, weight in graph.neighbors(node)
    }
    total = 0.0
    for step_source, step_target in zip(path, path[1:]):
        if (step_source, step_target) not in weights:
            raise AssertionError(f"path walks a missing edge: {step_source}->{step_target}")
        total += weights[(step_source, step_target)]
    if total != distance:
        raise AssertionError(f"path weight {total} != distance {distance} along {path}")
    return path


def algorithms_snapshot(graph: Graph) -> dict[str, object]:
    """The complete algorithm surface that is defined for this state, answers and refusals alike.

    Every call is captured as ``(kind, payload)``: a normal result or the raised error's kind and
    full evidence document, so "this state has no defined answer" and the evidence itself are
    compared exactly, not just the successful results.
    """
    nodes = graph.nodes()
    snap: dict[str, object] = {}
    for source in nodes:
        results: dict[str, object] = {
            "bfs": capture(lambda s=source: bfs(graph, s)),
            "dfs": capture(lambda s=source: dfs(graph, s)),
            "dijkstra": capture(lambda s=source: dijkstra(graph, s)),
            "bellman": capture(lambda s=source: bellman_ford(graph, s)),
        }
        # Bellman-Ford defines the reachable set even with negative edges; for every reachable
        # target run A* with an all-zero heuristic. On non-negative graphs it must return the same
        # distance (zero heuristic degenerates A* to Dijkstra); on negative graphs it must refuse
        # with the same NegativeWeightError on every backend.
        astar_outcomes: dict[str, object] = {}
        rebuilt_paths: dict[str, list[str]] = {}
        bellman_outcome = results["bellman"]
        if bellman_outcome[0] == "ok":
            bellman_distances, bellman_previous = bellman_outcome[1]
            zero_heuristic = {node: 0.0 for node in nodes}
            for target in sorted(bellman_distances):
                astar_outcomes[target] = capture(
                    lambda s=source, t=target, h=zero_heuristic: astar(graph, s, t, h)
                )
                rebuilt_paths[f"bellman:{target}"] = verified_path(
                    graph, bellman_previous, source, target, bellman_distances[target]
                )
                if astar_outcomes[target][0] == "ok":
                    distance, astar_previous, _ = astar_outcomes[target][1]
                    # The all-zero-heuristic distance must equal the shortest-path distance.
                    if distance != bellman_distances[target]:
                        raise AssertionError(
                            f"astar distance {distance} != bellman distance {bellman_distances[target]}"
                        )
                    rebuilt_paths[f"astar:{target}"] = verified_path(
                        graph, astar_previous, source, target, distance
                    )
        dijkstra_outcome = results["dijkstra"]
        if dijkstra_outcome[0] == "ok":
            dijkstra_distances, dijkstra_previous = dijkstra_outcome[1]
            for target in sorted(dijkstra_distances):
                rebuilt_paths[f"dijkstra:{target}"] = verified_path(
                    graph, dijkstra_previous, source, target, dijkstra_distances[target]
                )
        results["astar"] = astar_outcomes
        results["paths"] = rebuilt_paths
        snap[f"source:{source}"] = results
    snap["components"] = capture(lambda: components(graph))
    snap["centrality"] = capture(lambda: degree_centrality(graph))
    snap["clustering"] = capture(lambda: clustering(graph).to_document())
    snap["pagerank"] = capture(lambda: pagerank(graph).to_document())
    snap["communities"] = capture(lambda: label_propagation(graph).to_document())
    if graph.directed:
        snap["toposort"] = capture(lambda: topological_sort(graph))
    return snap


def full_snapshot(graph: Graph) -> dict[str, object]:
    return {"reads": read_snapshot(graph), "algorithms": algorithms_snapshot(graph)}


# -- the differential harness ---------------------------------------------------------------------
class StateSequenceDifferentialTests(unittest.TestCase):
    def apply_edit(self, graph: Graph, operation: Operation):
        """Replay one edit operation, normalising a ValidationError to kind plus full evidence."""
        kind = operation[0]
        try:
            if kind == "node":
                graph.add_node(operation[1])
                return "ok", None
            if kind == "edge":
                graph.add_edge(operation[1], operation[2], operation[3])
                return "ok", None
            if kind == "remove":
                return "ok", graph.remove_edge(operation[1], operation[2])
        except ValidationError as error:
            return "error", ("validation_error", error.to_document())
        raise AssertionError(f"unknown operation kind: {kind}")

    def assert_storage_report(
        self, report: dict[str, object], graph: Graph, requested: str, context: str
    ) -> None:
        entries, csr_bytes, dense_bytes = graph.storage_sizes()
        n = graph.node_count
        selected = expected_selection(requested, n, csr_bytes, dense_bytes)
        logical_bytes = dense_bytes if selected == "dense" else csr_bytes
        self.assertEqual(report["requested"], requested, context)
        self.assertEqual(report["selected"], selected, context)
        self.assertEqual(report["logicalBytes"], logical_bytes, context)
        self.assertEqual(report["adjacencyEntries"], entries, context)
        self.assertEqual(report["csrBytes"], csr_bytes, context)
        self.assertEqual(report["denseBytes"], dense_bytes, context)
        self.assertEqual(graph._storage, selected, context)
        self.assertEqual(graph._storage_requested, requested, context)

    def run_sequence(self, operations: list[Operation], directed: bool, seed: int, label: str) -> None:
        # The reference never leaves adjacency: configure_storage steps are no-ops for it, and the
        # twins' selection reports are validated against the operation plus the footprint formula.
        reference = Graph(directed=directed)
        twins = {backend: Graph(directed=directed) for backend in BACKENDS}

        for index, operation in enumerate(operations):
            context = f"{label} directed={directed} seed={seed} step={index} op={operation!r}"
            if operation[0] == "storage":
                requested = operation[1]
                reports = {}
                for backend in BACKENDS:
                    reports[backend] = twins[backend].configure_storage(requested)
                    twin_context = f"{context} backend={backend}"
                    self.assert_storage_report(reports[backend], twins[backend], requested, twin_context)
                # The same request on identical state must yield the byte-identical report.
                self.assertEqual(reports["dense"], reports["csr"], context)
                self.assertEqual(reports["auto"], reports["csr"], context)
                # Neutral fields must match the adjacency reference, which did not switch.
                expected_report = {
                    key: reports["csr"][key] for key in NEUTRAL_STORAGE_KEYS
                }
                self.assertEqual(neutral_storage_report(reference), expected_report, context)
            else:
                reference_outcome = self.apply_edit(reference, operation)
                for backend in BACKENDS:
                    twin_context = f"{context} backend={backend}"
                    outcome = self.apply_edit(twins[backend], operation)
                    # Same success/failure shape, same evidence, same remove-edge boolean.
                    self.assertEqual(outcome, reference_outcome, twin_context)

            expected = full_snapshot(reference)
            for backend in BACKENDS:
                twin_context = f"{context} backend={backend}"
                snapshot = full_snapshot(twins[backend])
                self.assertEqual(snapshot["reads"], expected["reads"], twin_context)
                self.assertEqual(snapshot["algorithms"], expected["algorithms"], twin_context)

    # -- main scenarios ---------------------------------------------------------------------------
    def test_mixed_sequences_stay_isomorphic_on_every_backend(self) -> None:
        for directed in (False, True):
            for seed in SEQUENCE_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(generate_sequence(seed, directed), directed, seed, "mixed")

    def test_switch_heavy_sequences_stay_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in SWITCH_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(
                        generate_switch_heavy_sequence(seed, directed), directed, seed, "switch-heavy"
                    )

    def test_edit_switch_churn_stays_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in MUTATION_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(
                        generate_mutation_switch_sequence(seed, directed), directed, seed, "edit-switch"
                    )

    # -- pinned structural scenarios that must appear regardless of generator shape ----------------
    def test_pinned_scenarios_each_keep_all_backends_isomorphic(self) -> None:
        pinned: list[list[Operation]] = [
            [("node", "a")],  # isolated node only
            [("edge", "a", "a", 2.0)],  # self-loop (mirror side included when undirected)
            [("edge", "a", "b", 0.0), ("node", "c")],  # zero-weight edge distinct from no edge
            [("edge", "a", "b", 9.0), ("edge", "a", "b", 1.0)],  # duplicate overwrite
            # Missing edge removed, then added, really removed, removed again: F, T, F.
            [("remove", "x", "y"), ("edge", "x", "y", 1.0), ("remove", "x", "y"), ("remove", "x", "y")],
            # Same-shape weight overwrite after each materialisation.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("edge", "a", "b", 4.0)],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("edge", "a", "b", 4.0)],
            # Edits after a switch on each materialised backend.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            # Consecutive switches between the materialised backends.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("storage", "dense"), ("storage", "csr"), ("storage", "dense")],
            # auto in every transition position.
            [("edge", "a", "b", 1.0), ("storage", "auto"), ("storage", "csr"), ("storage", "auto"), ("storage", "dense")],
            # Negative edges survive re-materialisation; refusal/accept split checked afterwards.
            [("edge", "a", "b", 1.0), ("edge", "b", "c", -2.0), ("storage", "dense"), ("storage", "csr")],
            # Directed cycle (toposort refusal) and a DAG (toposort order), seen through auto.
            [("edge", "a", "b", 1.0), ("edge", "b", "c", 1.0), ("edge", "c", "a", 1.0), ("storage", "auto")],
            [("edge", "a", "b", 1.0), ("edge", "b", "c", 1.0), ("edge", "a", "c", 1.0), ("storage", "auto")],
        ]
        for directed in (False, True):
            for number, operations in enumerate(pinned):
                with self.subTest(directed=directed, scenario=number):
                    self.run_sequence(operations, directed, number, f"pinned-{number}")


class RejectionInvarianceTests(unittest.TestCase):
    """Invalid inputs raise ValidationError and leave the whole observable state untouched."""

    INVALID_EDGE_CALLS = (
        ("", "b", 1.0),
        ("a", "", 1.0),
        ("a", "b", "1.5"),
        ("a", "b", None),
        ("a", "b", True),
        ("a", "b", float("nan")),
        ("a", "b", float("inf")),
        ("a", "b", float("-inf")),
    )

    def snapshot(self, graph: Graph) -> dict[str, object]:
        return {
            "state": full_snapshot(graph),
            "storage": graph._storage,
            "requested": graph._storage_requested,
        }

    def test_rejected_calls_change_nothing_on_every_backend(self) -> None:
        for directed in (False, True):
            for backend in ALL_SELECTIONS:
                with self.subTest(directed=directed, backend=backend):
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 2.0)
                    graph.add_edge("b", "c", 0.0)
                    graph.add_edge("a", "a", 3.0)
                    graph.add_node("iso")
                    graph.configure_storage(backend)
                    before = self.snapshot(graph)
                    for source, target, weight in self.INVALID_EDGE_CALLS:
                        with self.assertRaises(ValidationError):
                            graph.add_edge(source, target, weight)
                    with self.assertRaises(ValidationError):
                        graph.add_node("")
                    # Nodes, edges, the active/requested storage selection and every algorithm
                    # result are exactly what they were before the rejected calls.
                    self.assertEqual(self.snapshot(graph), before)

    def test_rejection_evidence_is_identical_across_backends(self) -> None:
        for directed in (False, True):
            for source, target, weight in self.INVALID_EDGE_CALLS:
                documents = {}
                for backend in ALL_SELECTIONS:
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 1.0)
                    graph.configure_storage(backend)
                    with self.assertRaises(ValidationError) as caught:
                        graph.add_edge(source, target, weight)
                    documents[backend] = caught.exception.to_document()
                context = (directed, source, target, weight)
                self.assertEqual(documents["csr"], documents["adjacency"], context)
                self.assertEqual(documents["dense"], documents["adjacency"], context)
                self.assertEqual(documents["auto"], documents["adjacency"], context)
                with self.assertRaises(ValidationError):
                    Graph(directed=directed).add_node("")

    def test_remove_missing_edge_returns_false_on_every_backend(self) -> None:
        for directed in (False, True):
            for backend in ALL_SELECTIONS:
                with self.subTest(directed=directed, backend=backend):
                    graph = Graph(directed=directed)
                    graph.add_edge("a", "b", 1.0)
                    graph.add_node("iso")
                    graph.configure_storage(backend)
                    missing_pairs = [("x", "y"), ("a", "x"), ("iso", "b")]
                    if directed:
                        missing_pairs.append(("b", "a"))  # reverse arc absent when directed
                    for source, target in missing_pairs:
                        self.assertFalse(graph.remove_edge(source, target), (backend, source, target))
                    self.assertEqual(edge_tuples(graph), [("a", "b", 1.0)])
                    self.assertEqual(graph.node_count, 3)
                    self.assertEqual(graph.self_loops(), [])

    def test_invalid_weight_types_are_all_validation_errors_and_store_nothing(self) -> None:
        for weight in INVALID_WEIGHTS:
            for directed in (False, True):
                graph = Graph(directed=directed)
                graph.configure_storage("auto")
                with self.subTest(weight=weight, directed=directed):
                    with self.assertRaises(ValidationError):
                        graph.add_edge("a", "b", weight)
                self.assertEqual(graph.nodes(), [])
                self.assertEqual(graph.edge_count(), 0)
                self.assertEqual(graph.storage_document()["selected"], "csr")  # empty auto graph


if __name__ == "__main__":
    unittest.main()

toolUseResult.content:
"""Repeatable state-sequence differential tests across the storage backends.

One graph always stays on the mutable ``adjacency`` dict and is the isomorphism reference; three
twins replay the *exact* same fixed operation sequence on ``csr``, ``dense`` and ``auto``. After
every successful step the public observation surface is compared -- nodes, edges, neighbours,
degree, edge count, self loops, the CSR export, ``to_document``, storage footprints and the
selection report -- and, whenever the state's preconditions hold, the complete results of every
algorithm (BFS, DFS, Dijkstra, Bellman-Ford, components, centrality, clustering, PageRank, label
propagation; topological sort for directed states; A* with an all-zero heuristic for reachable
targets), plus a re-walk of every ``path_from`` reconstruction. The exception type and evidence of
identical calls must also agree across backends.

The sequences come from a tiny seeded integer generator (no third-party property library, no
clock or environment input): the same seeds always pick the same cases, and a failure names the
graph type, backend, seed and the first inconsistent step. The scenarios stably cover isolated
nodes, self-loops, zero-weight edges, duplicate overwrites, removing a missing edge, edits after
a switch, same-shape weight overwrites, and repeated switches between the materialised backends.
Empty node names and non-finite/non-numeric weights keep raising ``ValidationError`` and must
change neither nodes, edges, storage selection nor subsequent algorithm results; removing a
missing edge keeps returning ``False``.
"""

from __future__ import annotations

import unittest

from graphtk import (
    Graph,
    NegativeCycleError,
    NegativeWeightError,
    ValidationError,
    astar,
    bellman_ford,
    bfs,
    clustering,
    components,
    degree_centrality,
    dfs,
    dijkstra,
    label_propagation,
    path_from,
    pagerank,
    topological_sort,
)
from graphtk.graph import DENSE_LIMIT_BYTES

# Seeds are fixed lists: adding or removing a seed is an explicit, reviewable choice, never a
# random draw, so two runs of this file execute byte-for-byte identical cases.
SEQUENCE_SEEDS = list(range(12))
SWITCH_SEEDS = list(range(6))
MUTATION_SEEDS = list(range(6))
BACKENDS = ("csr", "dense", "auto")
ALL_SELECTIONS = ("adjacency", "csr", "dense", "auto")
NODE_NAMES = ("a", "b", "c", "d", "e", "f")

# Finite numbers only: a generated state never approaches the 512 MiB dense ceiling (n <= 8).
WEIGHT_CHOICES = (0, 0.0, 1, 2, -2, 3, -1, 4, 0, 1, 5, -3, 2.5)

# Rejected by _validated_weight / add_node exactly the way the public API rejects them.
INVALID_WEIGHTS = (True, False, "1.5", None, float("nan"), float("inf"), float("-inf"))

# Backend-neutral keys of the storage report; requested/selected/logicalBytes are checked against
# the operation and the footprint formula instead.
NEUTRAL_STORAGE_KEYS = ("adjacencyEntries", "csrBytes", "denseBytes", "density")


class SeededChoices:
    """Deterministic integer stream -- a seeded LCG, nothing read from the clock or environment.

    Only ``randrange`` and ``choice`` are needed; the hand-rolled stream keeps case selection
    independent of hash randomisation, process seeding and the wall clock.
    """

    __slots__ = ("state",)

    def __init__(self, seed: int) -> None:
        self.state = seed & 0xFFFFFFFF

    def randrange(self, stop: int) -> int:
        # Numerical Recipes constants; LCG low bits are weak, so consume the high half.
        self.state = (1664525 * self.state + 1013904223) & 0xFFFFFFFF
        return (self.state >> 16) % stop

    def choice(self, options):
        return options[self.randrange(len(options))]


# -- operation records ----------------------------------------------------------------------------
# Every record is a tuple so a replayed step is trivially reproducible in a failure message:
#   ("node", name)                     add_node
#   ("edge", source, target, weight)   add_edge
#   ("remove", source, target)         remove_edge -> bool
#   ("storage", selection)             configure_storage -> storage document
Operation = tuple


def generate_sequence(seed: int, directed: bool) -> list[Operation]:
    """A fixed 48-step mix of edits and switches for one seed/directedness pair.

    The opening builds structure (self-loops, zero weights and duplicate pairs are biased in), the
    middle interleaves edits with backend switches, the tail stresses removals. A fixed tail then
    guarantees the required scenarios occur in every seed at the same positions.
    """
    rng = SeededChoices(seed * 2 + (1 if directed else 0) * 7919)
    operations: list[Operation] = []
    for step in range(48):
        if step < 14:
            kind = rng.choice(("node", "edge", "edge", "edge", "remove"))
        elif step < 34:
            kind = rng.choice(("node", "edge", "edge", "remove", "storage", "storage"))
        else:
            kind = rng.choice(("edge", "edge", "remove", "remove", "storage"))
        if kind == "node":
            operations.append(("node", rng.choice(NODE_NAMES)))
        elif kind == "edge":
            source = rng.choice(NODE_NAMES)
            target = rng.choice(NODE_NAMES)
            if step < 14 and rng.randrange(3) == 0:
                target = source  # reliably create self-loops in the opening
            operations.append(("edge", source, target, rng.choice(WEIGHT_CHOICES)))
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES), rng.choice(NODE_NAMES)))
        else:
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
    # Fixed tail: the mandated scenarios appear in every sequence, at identical positions.
    operations.extend(
        [
            ("node", "iso"),  # isolated node
            ("edge", "z", "z", 0.0),  # zero-weight self-loop on a fresh node
            ("edge", "a", "b", 8.0),
            ("edge", "a", "b", 2.5),  # same shape, new weight: arrays must rebuild
            ("remove", "iso", "z"),  # never an edge: False on every backend
            ("storage", "csr"),
            ("storage", "dense"),
            ("storage", "csr"),  # consecutive switches between materialised backends
            ("edge", "d", "e", 0.0),  # edit after the switches
            ("remove", "d", "e"),
            ("storage", "auto"),
            ("node", "iso"),  # re-adding an existing node is a no-op success
        ]
    )
    return operations


def generate_switch_heavy_sequence(seed: int, directed: bool) -> list[Operation]:
    """Mostly storage switches with occasional edits: backend state survives rapid re-selection."""
    rng = SeededChoices(seed * 31 + (3 if directed else 0) * 104729)
    operations: list[Operation] = []
    for _ in range(36):
        kind = rng.choice(("storage", "storage", "storage", "edge", "remove", "node"))
        if kind == "storage":
            operations.append(("storage", rng.choice(ALL_SELECTIONS)))
        elif kind == "edge":
            operations.append(
                ("edge", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4]), rng.choice(WEIGHT_CHOICES))
            )
        elif kind == "remove":
            operations.append(("remove", rng.choice(NODE_NAMES[:4]), rng.choice(NODE_NAMES[:4])))
        else:
            operations.append(("node", rng.choice(NODE_NAMES[:4])))
    return operations


def generate_mutation_switch_sequence(seed: int, directed: bool) -> list[Operation]:
    """Edit on one materialised backend, switch to the other, edit, switch back: classic churn."""
    rng = SeededChoices(seed * 17 + (5 if directed else 0) * 13)
    operations: list[Operation] = [("storage", "csr")]
    for index in range(20):
        source = NODE_NAMES[rng.randrange(5)]
        target = NODE_NAMES[rng.randrange(5)]
        operations.append(("edge", source, target, rng.choice(WEIGHT_CHOICES)))
        operations.append(("storage", "dense" if index % 2 == 0 else "csr"))
        if rng.randrange(3) == 0:
            operations.append(("remove", source, target))
            operations.append(("storage", "auto"))
    return operations


# -- snapshotting ---------------------------------------------------------------------------------
def edge_tuples(graph: Graph) -> list[tuple[str, str, float]]:
    return [(edge.source, edge.target, edge.weight) for edge in graph.edges()]


def neutral_storage_report(graph: Graph) -> dict[str, object]:
    document = graph.storage_document()
    return {key: document[key] for key in NEUTRAL_STORAGE_KEYS}


def expected_selection(requested: str, n: int, csr_bytes: int, dense_bytes: int) -> str:
    """Independent re-derivation of configure_storage's resolution rule."""
    if requested != "auto":
        return requested
    selected = "csr" if n == 0 or csr_bytes <= dense_bytes else "dense"
    if selected == "dense" and dense_bytes > DENSE_LIMIT_BYTES:
        selected = "csr"
    return selected


def read_snapshot(graph: Graph) -> dict[str, object]:
    """Every public read the storage layer sits underneath (README-committed fields only)."""
    nodes = graph.nodes()
    return {
        "nodes": nodes,
        "node_count": graph.node_count,
        "edges": edge_tuples(graph),
        "edge_count": graph.edge_count(),
        "neighbors": {node: graph.neighbors(node) for node in nodes},
        "degrees": {node: graph.degree(node) for node in nodes},
        "self_loops": graph.self_loops(),
        "csr": graph.csr(),
        "to_document": graph.to_document(),
        "storage_sizes": graph.storage_sizes(),
        "storage_report": neutral_storage_report(graph),
    }


def capture(thunk):
    """Run a thunk, returning ``('ok', value)`` or ``('error', (kind, full_document))``."""
    try:
        return "ok", thunk()
    except NegativeWeightError as error:
        return "error", ("negative_weight_error", error.to_document())
    except NegativeCycleError as error:
        return "error", ("negative_cycle_error", error.to_document())
    except ValidationError as error:
        return "error", ("validation_error", error.to_document())


def verified_path(graph: Graph, previous, source: str, target: str, distance: float) -> list[str]:
    """Rebuild a predecessor path and prove it walks existing edges and sums to the distance."""
    path = path_from(previous, target)
    if path[0] != source or path[-1] != target:
        raise AssertionError(f"path endpoints mismatch: {path} for {source}->{target}")
    weights = {
        (node, neighbour): weight
        for node in graph.nodes()
        for neighbour, weight in graph.neighbors(node)
    }
    total = 0.0
    for step_source, step_target in zip(path, path[1:]):
        if (step_source, step_target) not in weights:
            raise AssertionError(f"path walks a missing edge: {step_source}->{step_target}")
        total += weights[(step_source, step_target)]
    if total != distance:
        raise AssertionError(f"path weight {total} != distance {distance} along {path}")
    return path


def algorithms_snapshot(graph: Graph) -> dict[str, object]:
    """The complete algorithm surface that is defined for this state, answers and refusals alike.

    Every call is captured as ``(kind, payload)``: a normal result or the raised error's kind and
    full evidence document, so "this state has no defined answer" and the evidence itself are
    compared exactly, not just the successful results.
    """
    nodes = graph.nodes()
    snap: dict[str, object] = {}
    for source in nodes:
        results: dict[str, object] = {
            "bfs": capture(lambda s=source: bfs(graph, s)),
            "dfs": capture(lambda s=source: dfs(graph, s)),
            "dijkstra": capture(lambda s=source: dijkstra(graph, s)),
            "bellman": capture(lambda s=source: bellman_ford(graph, s)),
        }
        # Bellman-Ford defines the reachable set even with negative edges; for every reachable
        # target run A* with an all-zero heuristic. On non-negative graphs it must return the same
        # distance (zero heuristic degenerates A* to Dijkstra); on negative graphs it must refuse
        # with the same NegativeWeightError on every backend.
        astar_outcomes: dict[str, object] = {}
        rebuilt_paths: dict[str, list[str]] = {}
        bellman_outcome = results["bellman"]
        if bellman_outcome[0] == "ok":
            bellman_distances, bellman_previous = bellman_outcome[1]
            zero_heuristic = {node: 0.0 for node in nodes}
            for target in sorted(bellman_distances):
                astar_outcomes[target] = capture(
                    lambda s=source, t=target, h=zero_heuristic: astar(graph, s, t, h)
                )
                rebuilt_paths[f"bellman:{target}"] = verified_path(
                    graph, bellman_previous, source, target, bellman_distances[target]
                )
                if astar_outcomes[target][0] == "ok":
                    distance, astar_previous, _ = astar_outcomes[target][1]
                    # The all-zero-heuristic distance must equal the shortest-path distance.
                    if distance != bellman_distances[target]:
                        raise AssertionError(
                            f"astar distance {distance} != bellman distance {bellman_distances[target]}"
                        )
                    rebuilt_paths[f"astar:{target}"] = verified_path(
                        graph, astar_previous, source, target, distance
                    )
        dijkstra_outcome = results["dijkstra"]
        if dijkstra_outcome[0] == "ok":
            dijkstra_distances, dijkstra_previous = dijkstra_outcome[1]
            for target in sorted(dijkstra_distances):
                rebuilt_paths[f"dijkstra:{target}"] = verified_path(
                    graph, dijkstra_previous, source, target, dijkstra_distances[target]
                )
        results["astar"] = astar_outcomes
        results["paths"] = rebuilt_paths
        snap[f"source:{source}"] = results
    snap["components"] = capture(lambda: components(graph))
    snap["centrality"] = capture(lambda: degree_centrality(graph))
    snap["clustering"] = capture(lambda: clustering(graph).to_document())
    snap["pagerank"] = capture(lambda: pagerank(graph).to_document())
    snap["communities"] = capture(lambda: label_propagation(graph).to_document())
    if graph.directed:
        snap["toposort"] = capture(lambda: topological_sort(graph))
    return snap


def full_snapshot(graph: Graph) -> dict[str, object]:
    return {"reads": read_snapshot(graph), "algorithms": algorithms_snapshot(graph)}


# -- the differential harness ---------------------------------------------------------------------
class StateSequenceDifferentialTests(unittest.TestCase):
    def apply_edit(self, graph: Graph, operation: Operation):
        """Replay one edit operation, normalising a ValidationError to kind plus full evidence."""
        kind = operation[0]
        try:
            if kind == "node":
                graph.add_node(operation[1])
                return "ok", None
            if kind == "edge":
                graph.add_edge(operation[1], operation[2], operation[3])
                return "ok", None
            if kind == "remove":
                return "ok", graph.remove_edge(operation[1], operation[2])
        except ValidationError as error:
            return "error", ("validation_error", error.to_document())
        raise AssertionError(f"unknown operation kind: {kind}")

    def assert_storage_report(
        self, report: dict[str, object], graph: Graph, requested: str, context: str
    ) -> None:
        entries, csr_bytes, dense_bytes = graph.storage_sizes()
        n = graph.node_count
        selected = expected_selection(requested, n, csr_bytes, dense_bytes)
        logical_bytes = dense_bytes if selected == "dense" else csr_bytes
        self.assertEqual(report["requested"], requested, context)
        self.assertEqual(report["selected"], selected, context)
        self.assertEqual(report["logicalBytes"], logical_bytes, context)
        self.assertEqual(report["adjacencyEntries"], entries, context)
        self.assertEqual(report["csrBytes"], csr_bytes, context)
        self.assertEqual(report["denseBytes"], dense_bytes, context)
        self.assertEqual(graph._storage, selected, context)
        self.assertEqual(graph._storage_requested, requested, context)

    def run_sequence(self, operations: list[Operation], directed: bool, seed: int, label: str) -> None:
        # The reference never leaves adjacency: configure_storage steps are no-ops for it, and the
        # twins' selection reports are validated against the operation plus the footprint formula.
        reference = Graph(directed=directed)
        twins = {backend: Graph(directed=directed) for backend in BACKENDS}

        for index, operation in enumerate(operations):
            context = f"{label} directed={directed} seed={seed} step={index} op={operation!r}"
            if operation[0] == "storage":
                requested = operation[1]
                reports = {}
                for backend in BACKENDS:
                    reports[backend] = twins[backend].configure_storage(requested)
                    twin_context = f"{context} backend={backend}"
                    self.assert_storage_report(reports[backend], twins[backend], requested, twin_context)
                # The same request on identical state must yield the byte-identical report.
                self.assertEqual(reports["dense"], reports["csr"], context)
                self.assertEqual(reports["auto"], reports["csr"], context)
                # Neutral fields must match the adjacency reference, which did not switch.
                expected_report = {
                    key: reports["csr"][key] for key in NEUTRAL_STORAGE_KEYS
                }
                self.assertEqual(neutral_storage_report(reference), expected_report, context)
            else:
                reference_outcome = self.apply_edit(reference, operation)
                for backend in BACKENDS:
                    twin_context = f"{context} backend={backend}"
                    outcome = self.apply_edit(twins[backend], operation)
                    # Same success/failure shape, same evidence, same remove-edge boolean.
                    self.assertEqual(outcome, reference_outcome, twin_context)

            expected = full_snapshot(reference)
            for backend in BACKENDS:
                twin_context = f"{context} backend={backend}"
                snapshot = full_snapshot(twins[backend])
                self.assertEqual(snapshot["reads"], expected["reads"], twin_context)
                self.assertEqual(snapshot["algorithms"], expected["algorithms"], twin_context)

    # -- main scenarios ---------------------------------------------------------------------------
    def test_mixed_sequences_stay_isomorphic_on_every_backend(self) -> None:
        for directed in (False, True):
            for seed in SEQUENCE_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(generate_sequence(seed, directed), directed, seed, "mixed")

    def test_switch_heavy_sequences_stay_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in SWITCH_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(
                        generate_switch_heavy_sequence(seed, directed), directed, seed, "switch-heavy"
                    )

    def test_edit_switch_churn_stays_isomorphic(self) -> None:
        for directed in (False, True):
            for seed in MUTATION_SEEDS:
                with self.subTest(directed=directed, seed=seed):
                    self.run_sequence(
                        generate_mutation_switch_sequence(seed, directed), directed, seed, "edit-switch"
                    )

    # -- pinned structural scenarios that must appear regardless of generator shape ----------------
    def test_pinned_scenarios_each_keep_all_backends_isomorphic(self) -> None:
        pinned: list[list[Operation]] = [
            [("node", "a")],  # isolated node only
            [("edge", "a", "a", 2.0)],  # self-loop (mirror side included when undirected)
            [("edge", "a", "b", 0.0), ("node", "c")],  # zero-weight edge distinct from no edge
            [("edge", "a", "b", 9.0), ("edge", "a", "b", 1.0)],  # duplicate overwrite
            # Missing edge removed, then added, really removed, removed again: F, T, F.
            [("remove", "x", "y"), ("edge", "x", "y", 1.0), ("remove", "x", "y"), ("remove", "x", "y")],
            # Same-shape weight overwrite after each materialisation.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("edge", "a", "b", 4.0)],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("edge", "a", "b", 4.0)],
            # Edits after a switch on each materialised backend.
            [("edge", "a", "b", 1.0), ("storage", "csr"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            [("edge", "a", "b", 1.0), ("storage", "dense"), ("node", "g"), ("edge", "g", "a", 3.0), ("remove", "a", "b")],
            # Consecutive switches between the materialised backends.
